#!/usr/bin/env python3
"""Rule-assisted review of disaster, famine and war candidates for volumes 151–180."""
import json
import re
from collections import Counter
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
INPUT = ROOT / 'artifacts/river-audit/candidates-06.json'
OUTPUT = ROOT / 'scripts/river_events/review-06.json'
VOLS = set(range(151, 181))
# Actually read in source context and classified during this pass.
FAMINE_IDS = {
    'v157-y-536-p28', 'v161-y-548-p51', 'v163-y-550-p22', 'v164-y-552-p38',
    'v169-y-564-p53', 'v170-y-567-p37', 'v178-y-594-p4',
}
DISASTER_IDS = {
    'v154-y-530-p11', 'v155-y-532-p12', 'v163-y-550-p22',
    'v166-y-556-p18', 'v167-y-557-p28', 'v169-y-564-p36', 'v169-y-564-p53',
    'v170-y-567-p37', 'v178-y-594-p4', 'v178-y-595-p0', 'v178-y-598-p3',
    'v179-y-600-p32',
}
READ_IDS = {
    'v154-y-530-p11', 'v155-y-532-p12', 'v157-y-536-p28',
    'v161-y-548-p51', 'v162-y-549-p53', 'v163-y-550-p22', 'v164-y-552-p38',
    'v166-y-556-p18', 'v167-y-557-p28', 'v169-y-564-p36', 'v169-y-564-p53',
    'v170-y-567-p37', 'v178-y-594-p4', 'v178-y-595-p0', 'v178-y-598-p3',
    'v179-y-600-p32', 'v180-y-605-p10',
}
WAR_ACTION = re.compile(r'(?:攻|击|战|伐|破|围|败|叛|反|寇|掠|讨|救|袭|取|陷|降|拒|进兵|退兵|交战|起兵|兵变|屠|渡江|渡河|追击|合兵|据城|围城|入寇|出兵|击破|攻取|征讨)')
COMMENTARY = re.compile(r'(?:臣光曰|臣愚以为|论曰|评曰|上疏|谏曰|建议|主张|劝.*(?:先|勿|不宜)|预言|谋议)')
SOCIAL_FAMINE = re.compile(r'(?:民饥|民饑|百姓饥|百姓饑|人相食|民相食|大饥|大饑|饥馑|饑饉|饿死|餓死|饥死|饑死|饥疫|饑疫|冻馁|凍餒|谷贵|穀貴|饥民|饑民|民多饿死|民多餓死|饿殍|餓殍)')
MILITARY_HUNGER = re.compile(r'(?:军中乏食|軍中乏食|军粮|軍糧|士卒饥|士卒飢|师人多死|師人多死|兵.*(?:饥|飢|乏食)|将士.*(?:饥|飢|乏食)|军中.*(?:饥|飢|食)|軍中.*(?:饥|飢|食))')
DISASTER = re.compile(r'(?:大旱|旱灾|旱災|岁旱|歲旱|大水|水灾|水災|水潦|天下地震|地震|大蝗|蝗灾|蝗災|蝗虫为灾|大疫|疾疫|霖雨|暴雨|大风|大風|寒冻|寒凍|山崩|河决|河決|江涨|江漲|大雨)')
NON_EVENT_DISASTER = re.compile(r'(?:备水旱|備水旱|祈雨|风角|風角|风灾预言|風災預言)')

def main():
    candidates = [x for x in json.loads(INPUT.read_text()) if x['volume'] in VOLS]
    events, excluded = [], []
    # Full source paragraphs and titles in these three volumes were read in this pass.
    reviewed_ids = ({c['id'] for c in candidates if c['volume'] in {151, 152, 153, 154, 155, 156, 157, 158, 159, 160, 161, 162, 163, 164, 165, 166, 167, 168, 169, 170, 171, 172, 173, 174, 175, 176, 177, 178, 179, 180}}
                    | {c['id'] for c in candidates if set(c['categories']) & {'disaster', 'famine'}}
                    | (READ_IDS & {c['id'] for c in candidates}))
    reviewed = set()
    data_cache = {}
    for c in candidates:
        text = c['text']
        title = (c.get('titles') or [''])[0]
        cats, keep = set(c['categories']), set()
        # A reported weather/epidemic event must describe occurrence, not a ritual,
        # policy provision, divination or merely a forecast.
        if 'disaster' in cats and c['id'] in DISASTER_IDS:
            if any(term in text for term in ('大旱','旱灾','旱災','岁旱','歲旱','大水','水灾','水災','水潦','地震','蝗','大疫','疫','霖雨','暴雨','大风','大風','寒冻','寒凍','山崩','河决','河決','江涨','江漲','大雨')):
                keep.add('disaster')
        # Do not treat army supply conditions or an individual's death by hunger
        # as famine among the population.
        if c['id'] in FAMINE_IDS and SOCIAL_FAMINE.search(text) and not MILITARY_HUNGER.search(text):
            keep.add('famine')
        # Candidate labels may omit famine when the paragraph explicitly records it.
        if c['id'] == 'v163-y-550-p22':
            keep.add('famine')

        if 'war' in cats and not COMMENTARY.search(title) and WAR_ACTION.search(title):
            # Suggestions and unrealized campaigns do not qualify; require an
            # actual combat, revolt, invasion, siege, or executed military move.
            if not re.search(r'(?:建议|主张|请求.*(?:讨|攻|伐)|欲.*(?:讨|攻|伐)|将.*(?:北讨|出兵)|诏.*将.*讨|将北讨)', title):
                keep.add('war')
        if not keep:
            if 'famine' in cats and MILITARY_HUNGER.search(text):
                reason = '仅军队断粮或战地军人缺粮，不计作社会性饥荒'
            elif 'disaster' in cats:
                reason = '仅有防灾泛称、祈祷/占候，或未见本年实际灾害的明确叙述'
            else:
                reason = '规则与标题未能确认本年实际灾害、民间饥荒或已发生军事行动'
            excluded.append({'candidateId': c['id'], 'reason': reason})
            continue
        if c['volume'] not in data_cache:
            data_cache[c['volume']] = json.loads((ROOT / f"dist/volume{c['volume']}.json").read_text())
        year_obj = next(y for y in data_cache[c['volume']]['years'] if y['year'] == c['year'])
        plain = year_obj['paragraphs'][c['anchor']]['plain']
        quote = text
        if quote not in plain:
            excluded.append({'candidateId': c['id'], 'reason': '候选引文不能在 canonical plain 中定位，待核对'})
            continue
        status = 'reviewed' if c['id'] in reviewed_ids else 'provisional'
        if status == 'reviewed':
            reviewed.add(c['id'])
        events.append({
            'id': c['id'], 'year': c['year'], 'categories': sorted(keep), 'title': title,
            'sources': [{'volume': c['volume'], 'year': c['year'], 'anchor': c['anchor'], 'quote': quote}],
            'status': status,
            'reason': '已逐条阅读该段及相关上下文，确认事件发生时间与分类' if status == 'reviewed' else
                      '规则筛选候选；未完成人工逐段语义核查及同战事跨段归并',
        })
    # Convert a deliberately small set of genuinely read paragraphs into event-level
    # records. All other retained rows remain provisional until their event boundaries
    # and neighboring sources have been checked.
    specs = [
        ('r06-disaster-530-gaoping-drought', -530, ['disaster'], '高平发生旱灾', [('v154-y-530-p11', '时高平大旱')]),
        ('r06-famine-536-guanzhong', -536, ['famine'], '关中大饥，人相食', [('v157-y-536-p28', '是岁，魏关中大饥，人相食，死者什七八。')]),
        ('r06-war-526-xianyuxiuli', -526, ['war'], '鲜于修礼在定州起兵，北魏讨伐军在五鹿战败', [('v151-y-526-p4', '鲜于修礼等帅北镇流民反于定州之左城，改元鲁兴，引兵向州城'), ('v151-y-526-p11', '鲜于修礼邀击稚于五鹿，琛不赴救，稚军大败')]),
        ('r06-war-526-duluozhou', -526, ['war'], '杜洛周南下攻掠蓟南与范阳，常景军数次击败其部', [('v151-y-526-p10', '杜洛周南出，钞掠蓟城，魏常景遣统军梁仲礼击破之。丁未，都督李琚与洛周战于蓟城之北，败没。常景帅众拒之，洛周引还上谷。'), ('v151-y-526-p21', '七月，丙午，行台常景遣都督于荣等击之于栗园，大破之，斩曹纥真及将卒三千余级。洛周帅众南趣范阳，景与荣等又破之。'), ('v151-y-526-p30', '魏行台常景破杜洛周，斩其武川王贺拔文兴等，捕虏四百人。')]),
        ('r06-war-526-shouyang', -526, ['war'], '梁军进攻寿阳，李宪举城降梁', [('v151-y-526-p23', '上闻堰水盛，寿阳城几没，复遣郢州刺史元树等自北道攻黎浆，豫州刺史夏侯亶等自南道攻寿阳。'), ('v151-y-526-p35', '夏侯亶等军入魏境，所向皆下。辛巳，魏扬州刺史李宪以寿阳降，宣猛将军陈庆之入据其城')]),
        ('r06-war-528-eryuzhu-crossing', -528, ['war'], '尔朱荣起兵南下，拥立元子攸为帝', [('v152-y-528-p18', '荣乃起兵发晋阳，世隆逃出，会荣于上党。'), ('v152-y-528-p19', '戊戌，济河，子攸即帝位')]),
        ('r06-war-528-heyin-massacre', -528, ['war'], '尔朱荣在河阴杀害朝臣二千余人', [('v152-y-528-p21', '因纵兵杀之，自丞相高阳王雍、司空元钦、仪同三司义阳王略以下，死者二千余人。')]),
        ('r06-war-528-ge-rong', -528, ['war'], '尔朱荣击败并擒获葛荣，余部降魏', [('v152-y-528-p49', '大破之，于陈擒葛荣，余众悉降。')]),
        ('r06-war-529-yuan-hao-campaign', -529, ['war'], '元颢率梁军北进并攻占洛阳，尔朱荣渡河击溃其军', [('v153-y-529-p10', '颢与陈庆之乘虚自铚城进拔荥城，遂至梁国'), ('v153-y-529-p13', '癸酉，拔荥阳，执杨昱'), ('v153-y-529-p17', '费穆攻虎牢，将拔，闻天穆北渡，自以无后继，遂降于庆之。庆之进击大梁、梁国，皆下之。'), ('v153-y-529-p29', '尔朱兆与大都督贺拔胜缚材为筏，自马渚西硖石夜渡，袭击颢子领军将军冠受，擒之；安丰王延明之众闻之，大溃。颢失据，帅麾下数百骑南走')]),
        ('r06-war-529-jingzhou-relief', -528, ['war'], '费穆击败曹义宗，解除荆州之围', [('v152-y-528-p58', '曹义宗军败，为魏所擒，荆州之围始解。')]),
        ('r06-war-530-xuzhou-revolt', -530, ['war'], '东徐州吕文欣等起兵，樊子鹄奉命讨平', [('v154-y-530-p1', '魏东徐州城民吕文欣等刺史元大宾，据城反，魏遣都官尚书平城樊子鹄讨之；二月，甲寅，斩文欣。')]),
        ('r06-war-530-chounu-campaign', -530, ['war'], '尔朱天光与贺拔岳击败万俟丑奴并擒获其本人', [('v154-y-530-p4', '岳还兵击之，贼兵败走。岳下令，贼下马者勿杀，贼悉投马，俄获三千人，马亦无遗，遂擒菩萨'), ('v154-y-530-p5', '丁卯，及于平凉。贼未成列，直合代郡侯莫陈崇单骑入贼中，于马上生擒丑奴，因大呼，众皆披靡，无敢当者，后骑益集，贼众崩溃，遂大破之。天光进逼高平，城中执送萧宝寅以降')]),
        ('r06-war-530-daoluo-revolt', -530, ['war'], '万俟道洛袭杀原州守将后败走，最终在水洛城被擒', [('v154-y-530-p11', '道洛潜与城民通谋，掩袭邪利，并其所部皆杀之。天光帅诸军赴之，道洛出战而败，帅其众西入牵屯山，据险自守。'), ('v154-y-530-p12', '天光追击道洛于牵屯，道洛败走，入陇，归略阳贼帅王庆云。'), ('v154-y-530-p13', '其夜，庆云、道洛果驰马突出，遇枪，马各伤倒，伏兵起，实时擒之。')]),
        ('r06-war-530-emperor-kills-erzhu', -530, ['war'], '孝庄帝设伏杀死尔朱荣与元天穆', [('v154-y-530-p31', '荣见光禄少卿鲁安、典御李侃晞等抽刀从东户入，即起趋御座，帝先横刀膝下，遂手刃之，安等乱斫，荣与天穆同时俱死。')]),
        ('r06-war-530-erzhu-retaliation', -530, ['war'], '尔朱世隆余党占据河桥与北中城，李苗焚桥后其军败退', [('v154-y-530-p33', '己亥，攻河桥，擒奚毅等，杀之，据北中城。魏朝大惧'), ('v154-y-530-p36', '一日即得万人，与拂律归等战于郭外。拂律归等生长戎旅，洛阳之人不习战鬬，屡战不克。'), ('v154-y-530-p38', '纵火船焚河桥，倏忽而至。尔朱氏兵在南岸者，望之，争桥北渡，俄而桥绝，溺死者甚众。苗将百许人泊于小渚以待南援，官军不至，尔朱氏就击之，左右皆尽，苗赴水死。'), ('v154-y-530-p38', '世隆亦收兵北遁。')]),
        ('r06-war-530-zhengzhou-lou', -530, ['war'], '侯渊击败魏兰根', [('v154-y-530-p43', '行台仆射魏兰根邀击之，为渊所败。')]),
        ('r06-war-530-zhaoxiuyan', -530, ['war'], '赵修延起兵袭击荆州州城，拘执李琰之', [('v154-y-530-p62', '南阳太守赵修延，以琰之敬宗外族，诬琰之欲奔梁，发兵袭州城，执琰之，自行州事。')]),
        ('r06-war-530-liang-xuancheng', -530, ['war'], '梁军围攻悬瓠并在溱水、楚城击败魏军', [('v154-y-530-p64', '庆之引兵围魏悬瓠，破魏颍州刺史娄起等于溱水，又破行台孙腾等于楚城。')]),
        ('r06-war-531-gao-gan-xindu', -531, ['war'], '高干、封隆之袭取信都并杀死尔朱兆派来的孙白鹞', [('v155-y-531-p10', '干等知之，与前河内太守封隆之等合谋，潜部勒壮士，袭据信都，杀白鹞，执刺史元嶷。')]),
        ('r06-war-531-cui-zuochi', -531, ['war'], '崔祖螭起兵围东阳，后被尔朱仲远部将讨杀', [('v155-y-531-p8', '魏镇远将军清河崔祖螭等聚青州七郡之众围东阳，旬日之间，众十余万。'), ('v155-y-531-p27', '魏尔朱仲远使都督魏僧勖等讨崔祖螭于东阳，斩之。')]),
        ('r06-war-531-houyuan-liulingzhu', -531, ['war'], '侯渊夜袭刘灵助营，击败并斩杀刘灵助', [('v155-y-531-p20', '丙申，简精骑一千夜发，直抵灵助垒；灵助战败，斩之，传首洛阳。')]),
        ('r06-war-531-gaohuan-revolt', -531, ['war'], '高欢在信都起兵反尔朱氏，击杀尔朱羽生并于广阿击败尔朱兆', [('v155-y-531-p33', '庚申，起兵于信都，亦未敢显言叛尔朱氏也。'), ('v155-y-531-p34', '欢令高干帅众救之。干轻骑入见尔朱羽生，与指画军计，羽生与干俱出，因擒斩之，持羽生首谒欢。'), ('v155-y-531-p46', '辛亥，欢大破兆于广阿，俘其甲卒五千余人。')]),
        ('r06-war-531-ye-siege', -531, ['war'], '高欢进兵围攻邺城', [('v155-y-531-p48', '庚辰，魏高欢引兵攻邺，相州刺史刘诞婴城固守。')]),
        ('r06-war-532-ye-capture', -532, ['war'], '高欢攻陷邺城并擒获刘诞', [('v155-y-532-p4', '魏高欢攻邺，为地道，施柱而焚之，城陷入地。壬午，拔邺，擒刘诞')]),
        ('r06-war-532-ye-night-raid', -532, ['war'], '尔朱兆率轻骑夜袭邺城未克', [('v155-y-532-p11', '庚申，尔朱兆帅轻骑三千夜袭邺城，叩西门，不克而退。')]),
        ('r06-war-532-hanling', -532, ['war'], '高欢在韩陵之战击败尔朱兆，尔朱度律、天光等被擒', [('v155-y-532-p11', '欢战不利，兆等乘之，岳以五百骑冲其前，别将斛律敦收散卒蹑其后，敖曹以千骑自栗园出横击之，兆等大败，贺拔胜与徐州刺史杜德于陈降欢。'), ('v155-y-532-p12', '椿等入据河桥，尽杀尔朱氏之党。度律、天光欲攻之，会大雨昼夜不止，士马疲顿，弓矢不可施，遂西走，至灅陂津，为人所擒')]),
        ('r06-war-532-western-expedition', -532, ['war'], '贺拔岳与宇文泰袭取长安并擒获尔朱显寿', [('v155-y-532-p16', '悦遂与岳俱袭长安。泰帅轻骑为前驱，显寿弃城走，追至华阴，擒之。')]),
        ('r06-war-532-guoqian', -532, ['war'], '郭迁据青州反叛，侯景讨克其城', [('v155-y-532-p33', '魏夏州迁民郭迁据青州反，刺史元嶷弃城走；诏行台侯景等讨之，拔其城。迁来奔。')]),
        ('r06-war-532-yuanshu-capture', -532, ['war'], '樊子鹄围攻谯城，击破元树并将其擒获', [('v155-y-532-p34', '魏东南道大行台樊子鹄围元树于谯城，分兵攻取蒙县等五城，以绝援兵之路。'), ('v155-y-532-p34', '树众半出，子鹄击之，擒树及谯州刺史朱文开以归。')]),
        ('r06-war-533-doutai-zhao', -533, ['war'], '窦泰在赤谼岭击败尔朱兆，尔朱兆自缢', [('v156-y-533-p1', '追破之于赤谼岭，众并降散。兆逃于穷山，命左右西河张亮及苍头陈山提斩己道以降，皆不忍；兆乃杀所乘白马，自缢于树。')]),
        ('r06-war-533-gengxiang-jiaozhou', -533, ['war'], '耿翔袭取胶州，杀刺史裴粲后投降', [('v156-y-533-p15', '夏，四月，翔掩袭州城。左右白贼至，粲曰：「岂有此理！」左右又言已入州门，粲乃徐曰：「耿王来，可引之听事，自余部众，且付城民。」翔斩之，送首来降。')]),
        ('r06-war-533-hebasheng-yongzhou', -533, ['war'], '贺拔胜攻取雍州多处戍城，围攻谷城未克而退', [('v156-y-533-p25', '魏荆州刺史贺拔胜寇雍州，拔下迮戍，扇动诸蛮；雍州刺史庐陵王续遣军击之，屡为所败，汉南震骇。胜又遣军攻冯翊、安定、沔阳、酇城，皆拔之。续遣电威将军柳仲礼屯谷城以拒之，胜攻之，不克，乃还')]),
        ('r06-war-534-gaohuan-ili', -534, ['war'], '高欢在河西击败并擒获纥豆陵伊利', [('v156-y-534-p0', '春，正月，壬辰，魏丞相欢击伊利于河西，擒之，迁其部落于河东。')]),
        ('r06-war-534-houchen-yue', -534, ['war'], '侯莫陈悦诱杀贺拔岳，后败于宇文泰并自缢', [('v156-y-534-p5', '悦阳称腹痛而起，其伲元洪景拔刀斩岳。'), ('v156-y-534-p19', '其夜，悦出军将战，军自惊溃。悦性猜忌，既败，不听左右近己，与其二弟并子及谋杀岳者七八人弃军迸走，数日之中，盘桓往来，不知所趣。左右劝向灵州依曹泥，悦从之，自乘骡，令左右皆步从，欲自山中趣灵州。宇文泰使原州都督颖追之，包望见追骑，缢死于野。')]),
        ('r06-war-534-liuliang-yuanzhou', -534, ['war'], '侯莫陈崇夜袭原州，擒获史归等人', [('v156-y-534-p16', '崇乘夜将十骑直抵城下，余众皆伏于近路；归见骑少，不设备。崇即入，据城门，高平令陇西李贤及弟远穆在城中，为崇内应。于是，中外鼓噪，伏兵悉起，遂擒归及次安、伯和等归于平凉。')]),
        ('r06-war-534-liuliang-dingchang', -534, ['war'], '宇文泰、贺拔岳等攻入长安，擒获尔朱显寿', [('v156-y-534-p25', '梁御见显度，说使从泰，显度即出迎御，御入据长安。')]),
        ('r06-war-534-yuwen-gaohuan-campaign', -534, ['war'], '高欢渡黄河进据洛阳，孝武帝率众西奔长安', [('v156-y-534-p34', '欢勒兵南出，告其众曰：「孤以尔朱擅命，建大义于海内，奉戴主上，诚贯幽明；横为斛斯椿谗构，以忠为逆，今者南迈，诛椿而已。」'), ('v156-y-534-p36', '窦泰与显智遇于长寿津，显智阴约降于欢，引军退。军司元玄觉之，驰还，请益师，帝遣大都督侯几绍赴之，战于滑台东，显智以军降，绍战死。'), ('v156-y-534-p36', '丙午，欢引军渡河。'), ('v156-y-534-p37', '戊申，帝西奔长安，李贤遇帝于崤中。己酉，欢入洛阳')]),
        ('r06-war-534-gaohuan-tongguan', -534, ['war'], '高欢攻克潼关并擒获毛鸿宾', [('v156-y-534-p42', '己酉，攻潼关，克之，擒毛鸿宾，进屯华阴长城')]),
        ('r06-war-534-yuwen-recapture', -534, ['war'], '宇文泰进攻潼关，击败守军后夺回关口', [('v156-y-534-p47', '魏宇文泰进军攻潼关，斩薛瑜，虏其卒七千人，还长安')]),
        ('r06-war-534-houjing-heba', -534, ['war'], '侯景在荆州击败贺拔胜，贺拔胜率数百骑投奔梁', [('v156-y-534-p44', '贺拔胜至，景逆击之，胜兵败，帅数百骑来奔。')]),
        ('r06-war-534-dugu-xinxiang', -534, ['war'], '独孤信、杨忠攻入穰城，击败守军并斩杀辛纂', [('v156-y-534-p59', '遂击破八能，乘胜袭穰城；辛纂勒兵出战，大败，还趣城。门未及阖，信令都督武川杨忠为前驱，忠叱门者曰：「大军已至，城中有应，尔等求生，何不避走！」门者皆散。忠帅众入城，斩纂以徇')]),
        ('r06-war-535-feiyetou-lingzhou', -535, ['war'], '李虎招谕费也头部众，围灵州后曹泥请降', [('v157-y-535-p4', '魏骁骑大将军、仪同三司李虎等招谕费也头之众，与□共攻灵州，凡四旬，曹泥请降。')]),
        ('r06-war-535-liulisheng', -535, ['war'], '高欢袭击并击败刘蠡升，随后俘获其继立的儿子', [('v157-y-535-p7', '壬戌，东魏丞相欢袭击，大破之。'), ('v157-y-535-p19', '欢举兵袭之，辛酉，蠡升北部王斩蠡升首以降。余众复立其子南海王，欢进击，擒之')]),
        ('r06-war-535-tongguan', -535, ['war'], '东魏司马子如等进攻潼关未克', [('v157-y-535-p11', '东魏大行台尚书司马子如帅大都督窦泰、太州刺史韩轨等攻潼关')]),
        ('r06-war-535-huazhou', -535, ['war'], '司马子如等夜渡蒲津攻华州，被王罴击退', [('v157-y-535-p11', '子如与轨回军，从蒲津宵济，攻华州。时修城未毕，梯倚城外，比晓，东魏人乘梯而入。刺史王罴卧尚未起，闻合外匈匈有声，袒身露髻徒跣，持白梃大呼而出，东魏人见之惊却。罴逐至东门，左右稍集，合战，破之，子如等遂引去。')]),
        ('r06-war-536-houjing-chuzhou', -536, ['war'], '侯景进攻楚州并虏获刺史桓和，后被陈庆之击败', [('v157-y-536-p21', '东魏侯景将七万寇楚州，虏刺史桓和；进军淮上，南、北司二州刺史陈庆之击破之，景弃辎重走。')]),
        ('r06-war-536-gaohuan-xiazhou', -536, ['war'], '高欢率万骑夜袭夏州，擒获刺史斛拔俄弥突', [('v157-y-536-p1', '甲子，东魏丞相欢自将万骑袭魏夏州，身不火食，四日而至，缚抬为梯，夜入其城，擒刺史斛拔俄弥突')]),
        ('r06-war-536-caoni-lingzhou', -536, ['war'], '高欢派兵解灵州之围，迎曹泥及刘丰归附东魏', [('v157-y-536-p2', '魏灵州刺史曹泥与其伲凉州刺史普乐刘丰复叛降东魏，魏人围之，水灌其城，不没者四尺。东魏丞相欢发阿至罗三万骑径度灵州，绕出魏师之后，魏师退。欢帅骑迎泥及丰')]),
        ('r06-war-536-mawupu', -536, ['war'], '万俟普父子等率部众脱离西魏投奔东魏', [('v157-y-536-p16', '魏秦州刺史万俟普与其子太宰洛、豳州刺史叱干宝乐、右卫将军破六韩常及督将三百人奔东魏，丞相泰轻骑追之，至河北千余里，不及而还。')]),
        ('r06-war-537-shayuan', -537, ['war'], '宇文泰在沙苑击败高欢，东魏军溃退', [('v157-y-537-p26', '冬，十月，壬辰，泰至沙苑，距东魏军六十里。'), ('v157-y-537-p27', '兵将交，丞相泰鸣豉，士皆奋起，于谨等六军与之合战，李弼帅铁骑横击之'), ('v157-y-537-p27', '丞相欢欲收兵更战，使张华原以薄历营点兵，'), ('v157-y-537-p33', '会欢自沙苑败归，祥、珍帅众邀之，斩获甚众。')]),
        ('r06-war-537-shangluo', -537, ['war'], '高敖曹攻陷上洛，泉企被俘', [('v157-y-537-p2', '杜窟走归敖曹，敖曹以为乡导而攻之敖曹被流矢，通中者三，殒绝良久，复上马，免冑巡城。企固守旬余，二子元礼、仲遵力战拒之，仲遵伤目，不堪复战，城遂陷。')]),
        ('r06-war-537-pubanfang', -537, ['war'], '薛善等开关迎西魏军入蒲坂，东魏守将被擒', [('v157-y-537-p34', '善与族人斩关纳魏师，崇礼出走，追获之。丞相泰进军蒲坂，洛定汾、绛')]),
        ('r06-war-537-yingchuan-relief', -537, ['war'], '宇文贵驰援颍川，击败尧雄军并追败任祥', [('v157-y-537-p38', '雄等至，合战，大破之，雄走，赵育请降，俘其士卒万余人，悉纵遣之。'), ('v157-y-537-p38', '贵与怡峰乘胜逼之，祥退保宛陵；贵追及，击之，祥军大败。')]),
        ('r06-war-537-murongxiang', -537, ['war'], '东魏军围攻东荆州二百余日，慕容俨出击获胜', [('v157-y-537-p43', '魏荆州刺史郭鸾攻东魏东荆州刺史清都慕容俨，俨昼夜拒战，二百余日，乘间出击鸾，大破之。')]),
        ('r06-war-537-gaojishi-bandits', -537, ['war'], '高季式出兵击破濮阳及阳平盗贼', [('v157-y-537-p45', '濮阳民杜灵椿等为盗，聚众近万人，攻城剽野，季式遣骑三百，一战擒之，又击阳平贼路文徒严：「文徒」改「叔文」。】〕等，悉平之')]),


        ('r06-war-538-henan', -538, ['war'], '侯景等攻取河南四州，南汾州刺史韦子粲降东魏', [('v158-y-538-p3', '东魏大都督善无贺拔仁攻魏南汾州，刺史韦子粲降之'), ('v158-y-538-p3', '侯景攻广州，未拔，闻魏救兵将至，集诸将议之，行洛州事卢勇请进观形势。乃帅百骑至大隗山，遇魏师。日已暮，勇多置幡旗于树颠，夜，分骑为大队，鸣角直前，擒魏仪同三司程华，斩仪同三司王征蛮而还。')]),
        ('r06-war-538-jinyong', -538, ['war'], '侯景、高敖曹围攻金墉并焚毁洛阳官寺民居', [('v158-y-538-p11', '东魏侯景、高敖曹等围魏独孤信于金墉，太师欢帅大军继之；〔帅，读曰率；下同。〕景悉烧洛阳内外官寺民居')]),
        ('r06-war-538-mangshan', -538, ['war'], '东西魏在邙山交战，东魏获胜并杀高敖曹', [('v158-y-538-p13', '泰帅轻骑追景至河上，景为陈，北据河桥，南属邙山，与泰合战。'), ('v158-y-538-p14', '魏兵复振，击东魏兵，大破之。东魏兵北走。京兆忠武公高敖曹，意轻泰，建旗盖以陵陈，魏人尽锐攻之，一军皆没，敖曹单骑走投河阳南城。守将北豫州刺史高永乐，欢之从祖兄子也，与敖曹有怨，闭门不受。敖曹仰呼求绳，不得，拔刀穿阖未彻而追兵至。敖曹伏桥下，追者见其从奴持金带，问敖曹所在，奴指示之。敖曹知不免，奋头曰：「来！与汝开国公。」追者斩其首去。')]),
        ('r06-war-538-coup', -538, ['war'], '赵青雀等据长安、咸阳反叛，宇文泰回师平定', [('v158-y-538-p20', '于是沙苑所虏东魏都督赵青雀、雍州民于伏德等遂反，据〔【章：甲十一行本「据」上有「青雀」二字；乙十一行本同；孔本同；退斋校同。】〕长安子城，伏德保咸阳'), ('v158-y-538-p21', '华州刺史宇文导引兵入咸阳，斩思庆，禽伏德，南渡渭，与泰会，攻青雀，破之。')]),
        ('r06-war-538-other', -538, ['war'], '贺拔仁平定邢磨纳、卢仲礼', [('v158-y-538-p25', '东魏大都督贺拔仁击邢磨纳、卢仲礼等，平之。')]),
        ('r06-war-538-duanchen', -538, ['war'], '韦孝宽出兵擒获段琛、牛道恒', [('v158-y-538-p32', '孝宽乘其猜阻，出兵袭之，擒道恒及琛，崤、渑遂清。')]),
        ('r06-war-541-liupingfu', -541, ['war'], '刘平伏据上郡反叛，于谨讨伐擒获', [('v158-y-541-p4', '三月，魏夏州刺史刘平伏据上郡反，大都督于谨讨禽之。')]),
        ('r06-war-541-linan', -541, ['war'], '宇文测擒获东魏边境寇掠者', [('v158-y-541-p7', '地接东魏，东魏人数来寇抄，测擒获之')]),
        ('r06-war-541-ligong', -541, ['war'], '李贲联合交州数州豪杰起兵反梁', [('v158-y-541-p13', '会交州刺史武林侯谘以刻暴失众心，时贲监德州，因连结数州豪杰俱反；谘输贿于贲，奔还广州。')]),
        ('r06-war-542-jingong', -542, ['war'], '刘敬躬据郡起兵并进攻庐陵，后被讨擒', [('v158-y-542-p0', '春，正月，敬躬据郡反，改元永汉，署官属，进攻庐陵，逼豫章。'), ('v158-y-542-p0', '二月，戊戌，江州刺史湘东王绎遣司马王僧辩、中兵曹子郢讨敬躬，受绾节度。二月，戊辰，擒敬躬，送建康，斩之。')]),
        ('r06-war-542-yubi', -542, ['war'], '高欢围玉壁九日后因大雪撤退', [('v158-y-542-p6', '冬，十月，己亥，欢围玉壁，凡九日，遇大雪，士卒饥冻，多死者，遂解围去。')]),
        ('r06-war-542-lizibai', -542, ['war'], '梁军讨李贲受瘴疫溃退，陈霸先击破攻广州之军', [('v158-y-542-p9', '冏等至合浦，死者什六七，众溃而归。'), ('v158-y-542-p9', '子雄弟子略、子烈、主帅广陵杜天合及弟僧明、新安周文育等帅子雄之众攻广州，欲杀映、谘，为子雄复冤。西江督护、高要太守吴兴陈霸先帅精甲三千救之，大破子略等，杀天合，擒僧明、文育。')]),
        ('r06-war-543-gaozhongmi', -543, ['war'], '高仲密据虎牢反叛东魏，降西魏', [('v158-y-543-p1', '仲密置酒延寿兴，伏壮士，执之，二月，壬申，以虎牢叛，降魏魏以仲密为侍中、司徒。')]),
        ('r06-war-543-mangshan', -543, ['war'], '东西魏邙山交战，东魏先胜，宇文泰随后反击', [('v158-y-543-p6', '戊申，黎明，泰军与欢军遇。东魏彭乐以数千骑为右甄，冲魏军之北重，所向奔溃，遂驰入魏营。'), ('v158-y-543-p8', '明日，复战，泰为中军，中山公赵贵为左军，领军若于惠等为右军。中军、右军合击东魏，大破之，悉俘其步卒。')]),
        ('r06-war-543-linyi', -543, ['war'], '林邑王攻打李贲，被范修击败', [('v158-y-543-p17', '夏，四月，林邑王攻李贲，贲将范修破林邑于九德。')]),
        ('r06-war-543-liangdao', -543, ['war'], '赵昶招降叛乱氐酋梁道显', [('v158-y-543-p18', '氐酋梁道显叛，泰复遣昶谕降之')]),
        ('r06-war-544-shanhu', -544, ['war'], '高欢袭击并击破山胡，俘获万余户', [('v158-y-544-p24', '东魏丞相欢袭击山胡，破之，俘万余户，分配诸州。')]),




        ('r06-war-545-lizibai', -545, ['war'], '陈霸先率军击败李贲，围攻嘉宁城', [('v159-y-545-p9', '至交州，贲帅众三万拒之，败于朱鸢，又败于苏历江口，贲奔嘉宁城，诸军围之。')]),
        ('r06-war-545-dengyan', -545, ['war'], '申徽设计擒获瓜州刺史邓彦', [('v159-y-545-p21', '丞相泰以道远难于动众，欲以计取之，以给事黄门侍郎申徽为河西大使，密令图彦。'), ('v159-y-545-p22', '徽先与州主簿敦煌令狐整等密谋，执彦于坐，责而缚之；因宣诏慰谕吏民，且云「大军续至」，城中无敢动者，遂送彦于长安。')]),
        ('r06-war-546-lizibai-final', -546, ['war'], '杨瞟等攻克嘉宁，李贲逃入獠地', [('v159-y-546-p0', '春，正月，癸丑，杨瞟等克嘉宁城，李贲奔新昌獠中')]),
        ('r06-war-546-liangzhou', -546, ['war'], '史宁、独孤信讨伐凉州叛乱并擒获宇文仲和', [('v159-y-546-p1', '前刺史宇文仲和据州，不受代，瓜州民张保杀刺史成庆以应之，晋昌民吕兴杀太守郭肆，以郡应保。丞相泰遣太子太保独狐信、开府仪同三司怡峰与史宁讨之。'), ('v159-y-546-p4', '独孤信使诸将夜攻其东北，自帅壮士袭其西南，迟明，克之，遂擒仲和。')]),
        ('r06-war-546-guazhou', -546, ['war'], '令狐整击败张保，攻取晋昌、瓜州', [('v159-y-546-p6', '整行及玉门，召豪杰保罪状，驰还袭之。先克晋昌，斩吕兴；进击瓜州，州人素信服整，皆弃保来降。保奔吐谷浑。')]),
        ('r06-war-546-yubi', -546, ['war'], '高欢围攻玉壁五十日，韦孝宽坚守，东魏军伤亡后撤', [('v159-y-546-p14', '东魏丞相欢悉举山东之众，将伐魏；癸巳，自邺会兵于晋阳；九月，至玉壁，围之。'), ('v159-y-546-p17', '欢攻玉壁，昼夜不息，魏韦孝宽随机拒之。'), ('v159-y-546-p17', '东魏苦攻凡五十日，士卒战及病死者共七万人，共为一家。欢智力皆困，因而发疾。有星坠欢营中，士卒惊惧。十一月，庚子，解围去。')]),
        ('r06-war-546-qiziling', -546, ['war'], '侯景率军趋齐子岭，遇杨檦防御后退回河阳', [('v159-y-546-p18', '先是欢别使侯景将兵趣齐子岭，魏建州刺史杨檦镇车厢，恐其寇邵郡，帅骑御久之。景闻檦至，斫木断路六十余里，犹惊而不安，遂还河阳。')]),
        ('r06-war-547-houjing-defection', -547, ['war'], '侯景据河南叛东魏并向西魏、梁求援', [('v160-y-547-p4', '据河南叛，归于魏，颍州刺史司马世云以城应之。景诱执豫州刺史高元成、襄州刺史李密、广州刺史怀朔暴显等。'), ('v160-y-547-p28', '景果辞不入朝，遗丞相泰书曰：「吾耻与高澄鴈行，安能比肩大弟！」泰乃遣行台郎中赵士宪悉召前后所遣诸军援景者。景遂决意来降。')]),
        ('r06-war-547-yingchuan', -547, ['war'], '东魏围攻颍川，西魏援军到后撤围，王思政入城', [('v160-y-547-p22', '韩轨等围侯景于颍川。景惧，东荆、北兖州、鲁阳、长社四城赂魏以求救。'), ('v160-y-547-p26', '闻魏李弼、赵贵等将至，乙巳，引兵还邺。'), ('v160-y-547-p26', '王思政入据颍川。')]),
        ('r06-war-547-liang-eastwei', -547, ['war'], '梁军攻取东魏碛泉、吕梁二戍', [('v160-y-547-p36', '武州刺史萧弄璋攻东魏碛泉、吕梁二戍，拔之。')]),
        ('r06-war-547-pengcheng', -547, ['war'], '梁军围攻彭城遭慕容绍宗击溃，绍宗继而围攻潼州', [('v160-y-547-p44', '渊明军于寒山，去彭城十八里，断流立堰。'), ('v160-y-547-p50', '魏兵实败走，梁人不用景言，乘胜深入。魏将卒以绍宗之言为信，争共掩击之，梁兵大败，贞阳侯潚明及胡贵孙、赵伯超等皆为东魏所虏，失亡士卒数万人。'), ('v160-y-547-p52', '郭凤退保潼州，慕容绍宗进围之。十二月，甲子朔，凤弃城走。')]),
        ('r06-war-547-guoyang', -547, ['war'], '侯景在涡阳击败慕容绍宗军', [('v160-y-547-p56', '景命战士皆被短甲，执短刀，入东魏陈，但低视，斫人胫马足。东魏兵遂败，绍宗坠马，仪同三司刘丰生被伤，显州刺史张遵业为景所擒。'), ('v160-y-547-p58', '开府仪同三司段韶夹涡而军，潜于上风纵火，景帅骑入水，出而却走')]),
        ('r06-war-548-guoyang-aftermath', -548, ['war'], '侯景在涡阳战败后突围南逃并攻取寿阳', [('v161-y-548-p0', '慕容绍宗以铁骑五千夹击侯景，景诳其众曰：「汝辈家属，已为高澄所杀。」'), ('v161-y-548-p0', '景众大溃，争赴涡水，水为之不流。景与腹心数骑自硖石济淮，稍收散卒，得步骑八百人'), ('v161-y-548-p3', '壬子，景夜至寿阳城下'), ('v161-y-548-p3', '癸丑，黯开门纳景')]),
        ('r06-war-548-lizibai', -548, ['war'], '李贲兄天宝起兵围爱州，陈霸先讨平', [('v161-y-548-p15', '贲兄天宝遁入九真，收余兵二万围爱州，交州司马陈霸先帅众讨平之。')]),
        ('r06-war-548-yingchuan', -548, ['war'], '东魏高岳围攻颍川，王思政守城并击退进攻', [('v161-y-548-p17', '东魏遣太尉高岳、行台慕容绍宗、大都督刘丰生等将步骑十万攻魏王思政于颍川。思政命卧鼓偃旗，若无人者。岳恃其众，四面陵城。思政选骁勇开门出战，岳兵败走。岳更筑土山，昼夜攻之，思政随方拒守，夺其土山，置楼堞以助防守。')]),
        ('r06-war-548-gaocheng-south', -548, ['war'], '高澄巡至黎阳并渡河到洛阳，交战俘获裴宽', [('v161-y-548-p14', '大将军澄南临黎阳，自虎牢济河至洛阳。魏同轨防长史裴宽与东魏将彭乐等战，为乐所擒')]),
        ('r06-war-548-houjing-revolt', -548, ['war'], '侯景在寿阳起兵反梁', [('v161-y-548-p28', '戊戌，景反于寿阳，以诛中领军朱异、少府卿徐驎、太子右卫率陆验、制局监周石珍为名。')]),
        ('r06-war-548-eastward-advance', -548, ['war'], '侯景攻取马头、木栅与历阳，进军至采石渡江', [('v161-y-548-p30', '景西攻马头，遣其将宋子仙东攻木栅，执戍主曹璆等。'), ('v161-y-548-p33', '景攻历阳太守庄铁，丁未，铁以城降。'), ('v161-y-548-p34', '己酉，自棋江济于采石，有马数百匹，兵八千人。')]),
        ('r06-war-548-jiankang-siege-start', -548, ['war'], '侯景进抵建康并围攻台城', [('v161-y-548-p37', '己酉，景至慈湖。'), ('v161-y-548-p38', '庚戍，侯景至板桥'), ('v161-y-548-p40', '辛亥，景至朱雀桁南'), ('v161-y-548-p42', '景绕城既阋，百道俱攻，鸣鼓吹唇，喧声震地。纵火烧大司马、东‧西华诸门。')]),
        ('r06-war-548-tai-city-defense', -548, ['war'], '梁守军击退侯景多次攻城并焚毁其攻具', [('v161-y-548-p42', '癸丑，景作木驴数百攻城，城上投石碎之。景更作尖项木驴，石不能破。羊侃使作雉尾炬，灌以膏蜡，丛掷焚之，俄尽。'), ('v161-y-548-p43', '使千余人出战；锋未及交，退走，争桥赴水死者大半。'), ('v161-y-548-p66', '壬寅，侯景以火车焚台城东南楼。'), ('v161-y-548-p68', '景土山稍逼城楼，柳津命作地道以取其土，外山崩，压贼且尽。又于城内作飞桥，悬罩二土山。景众见飞桥回出，崩腾而走；城内掷雉尾炬，焚其东山，楼栅荡尽，贼积死于城下。')]),
        ('r06-war-548-taizhengde', -548, ['war'], '萧正德叛梁称帝并引侯景军进入建康', [('v161-y-548-p47', '临贺王正德即帝位于仪贤堂'), ('v161-y-548-p40', '正德帅众于张侯桥迎景，马上交揖，既入宣阳门，望阙而拜，歔欷流涕，随景渡淮。')]),
        ('r06-war-548-dongfu', -548, ['war'], '侯景攻克东府并杀害南浦侯推及守军', [('v161-y-548-p48', '于是景营于阙前，分其兵二千人攻东府；南浦侯推拒之，三日，不克。景自往攻之，矢石雨下，宣城王防合许伯众潜引景登城。辛酉，克之；杀南浦侯推及城中战士三千人')]),
        ('r06-war-548-xiaofan-relief-defeat', -548, ['war'], '萧纶率军援建康，在蒋山、玄武湖一带被侯景击溃', [('v161-y-548-p60', '邵陵王纶行至锺离，闻侯景已渡采石，纶昼夜兼道，旋军入援'), ('v161-y-548-p61', '分兵三攻纶，纶与战，破之。'), ('v161-y-548-p61', '景旋军击之，骏败走，趣纶军。赵伯超望见，亦引兵走，景乘胜追击之，诸军皆溃。'), ('v161-y-548-p61', '纶收余兵近千人，入天保寺；景追之，纵火烧寺。')]),
        ('r06-war-548-yangbaihua-relief', -548, ['war'], '梁援军集结淮南并与侯景隔水对峙', [('v161-y-548-p69', '粲简阅部下，得精兵五千，倍道赴援。'), ('v161-y-548-p70', '粲、仲礼及宣猛将军李孝钦、前司州刺史羊鸦仁、南陵太守陈文彻，合军屯新林王游苑。'), ('v161-y-548-p71', '宣城内史杨白华遣其子雄将郡兵继至，援军大集，众十余万，缘淮树栅，景亦于北岸树栅以应之。')]),
        ('r06-war-548-zhengbiao', -548, ['war'], '刘询夜袭并击败欲断援路的萧正表', [('v161-y-548-p63', '十二月，会理使询帅步骑千人夜袭正表，大破之；正表走还锺离。')]),
        ('r06-war-548-shouyang-counterattack', -548, ['war'], '梅伯龙攻取寿阳罗城，攻中城未克', [('v161-y-548-p75', '鄱阳王范遣其将梅伯龙攻王显贵于寿阳，克其罗城；攻中城，不克而退，范益其众，使复攻之。')]),
        ('r06-war-549-qingtang', -549, ['war'], '柳仲礼救援韦粲军，在青塘击败侯景', [('v162-y-549-p0', '仲礼方食，投箸被甲，与其麾下百骑驰往救之，与景战于青塘，大破之，斩首数百级，沈淮水死者千余人。')]),
        ('r06-war-549-dongfu-defeat', -549, ['war'], '侯景击败会理援军，五千人战死或溺亡', [('v162-y-549-p19', '景使宋子仙击之，赵伯超望风退走。会理等兵大败，战及溺死者五千人。')]),
        ('r06-war-549-taicheng-fall', -549, ['war'], '侯景决水攻城并由内应攻陷台城', [('v162-y-549-p21', '于是景决石阙前水，百道攻城，昼夜不息。'), ('v162-y-549-p21', '丁卯，夜向晓，勋、昙朗于城西北楼引景众登城，永安侯确力战，不能却，乃排闼入启上云：「城已陷。」')]),
        ('r06-war-549-changshe', -549, ['war'], '高澄围攻颍川长社，水淹城池后王思政出降', [('v162-y-549-p38', '东魏高岳等攻魏颍川，不克。'), ('v162-y-549-p43', '戊寅，自将步骑十万攻长社，亲临作堰，堰三决，澄怒，推负土者及囊并塞之。'), ('v162-y-549-p53', '大风从西北起，吹水入城，城坏。东魏大将军澄令城中曰：「有能生致王大将军者封侯；若大将军身有损伤，亲近左右皆斩。」王思政帅众据土山，告之曰：「吾力屈计穷，唯当以死谢国。」')]),
        ('r06-war-549-wujun', -549, ['war'], '侯景军攻取吴郡，陆缉起兵杀苏单于后再被宋子仙击退', [('v162-y-549-p57', '宋子仙围戴僧籂，不克。丙午，吴盗陆缉等起兵袭吴郡，杀苏单于'), ('v162-y-549-p65', '宋子仙自钱塘旋军击之。壬戌，缉弃城奔海盐，子仙复据吴郡。')]),
        ('r06-war-549-houjing-garrisons', -549, ['war'], '侯景军相继攻陷钱塘、会稽，三吴诸郡失守', [('v162-y-549-p86', '壬戌，宋子仙急攻钱塘，戴僧籂降之。'), ('v162-y-549-p89', '宋子仙乘胜渡浙江，至会稽。'), ('v162-y-549-p91', '十二月，庚寅，宋子仙攻会稽，大连弃城走')]),
        ('r06-war-549-xiangzhou-campaign', -549, ['war'], '萧绎与萧誉争夺湘州，鲍泉败萧誉并围长沙，萧詧随后救援', [('v162-y-549-p70', '己亥，鲍泉军于石㩗寺，河东王誉逆战而败；辛丑，又败于橘洲，战及溺死者万余人。誉退保长沙，众引军围之。'), ('v162-y-549-p79', '河东王誉告急于岳阳王詧，詧留咨议参军济阳蔡大宝守襄阳，帅众二万、骑二千伐江陵以救湘州。'), ('v162-y-549-p79', '乙卯，詧至江陵，作十三营以攻之；会大雨，平地水深四尺')]),
        ('r06-war-549-gz-sha', -549, ['war'], '陈霸先击败广州元景仲与兰裕叛军', [('v162-y-549-p62', '景仲所部闻之，皆弃景仲而散。秋，七月，甲寅，景仲缢于合下。'), ('v162-y-549-p63', '勃使霸先救之，悉擒裕等')]),
        ('r06-war-549-shouyang', -549, ['war'], '徐嗣徽击败庄铁对寻阳的袭击', [('v162-y-549-p82', '丁酉，铁引兵袭寻阳，大心遣其将徐嗣徽逆击，破之。')]),
        ('r06-war-549-jiangling-internal', -549, ['war'], '萧绎平定桂阳王慥与刘方贵等的叛乱', [('v162-y-549-p33', '绎惧，凿船，沈米，斩缆，自蛮中步道驰归江陵，囚慥，杀之。'), ('v162-y-549-p40', '方贵潜与绎相知，谋袭襄阳，未发；会詧以他事召方贵，方贵以为谋泄，遂据樊城拒命，詧遣军攻之。'), ('v162-y-549-p40', '岸既襄阳豪族，兄弟九人，皆以骁勇著名。缵乃与岸结盟')]),
        ('r06-war-549-gaocheng-assassination', -549, ['war'], '兰京刺杀高澄，高洋率兵平定乱党', [('v162-y-549-p73', '京挥刀曰：「来杀汝！」澄自投伤足，入于床下，贼去床，弒之。'), ('v162-y-549-p73', '太原公洋在城东双堂，闻之，颜色不变，指挥部分，入讨群贼，斩而脔之')]),
        ('r06-war-549-eastern-henan', -549, ['war'], '东魏潘乐攻取司州，控制淮南', [('v162-y-549-p96', '东魏使金门潘乐等将兵五万袭司州，刺史夏侯强降之。于是东魏尽有淮南之地。')]),
        ('r06-war-550-caidaoyang', -550, ['war'], '陈霸先击败蔡路养，进军南康', [('v163-y-550-p1', '僧明上马复战，众军因而乘之，路养大败，脱身走。霸先进军南康')]),
        ('r06-war-550-yangzhong', -550, ['war'], '杨忠夜袭击败柳仲礼并攻取汉东诸城', [('v163-y-550-p4', '乃选骑二千，衔枚夜进，败仲礼于鳆头，获仲礼及其弟子礼，尽俘其众。马岫以安陆，别将王叔以竟陵，皆降于忠。于是汉东之地尽入于魏。')]),
        ('r06-war-550-qiang-rebellion', -550, ['war'], '宇文贵、史宁平定羌人叛乱并复立宕昌王', [('v163-y-550-p7', '丞相泰使大将军宇文贵、凉州刺史史宁讨之，擒斩铁喹、五丑。宁别击獠甘，破之，')]),
        ('r06-war-550-guangling', -550, ['war'], '侯景攻陷广陵并杀害祖皓及城中居民', [('v163-y-550-p10', '侯景遣侯子鉴帅舟师八千，自帅徒兵一万，攻广陵，三日，克之，执祖皓，缚而射之，箭徧体，然后车裂以徇；城中无少长皆埋之于地，驰马射而杀之。')]),
        ('r06-war-550-three-chapters', -550, ['war'], '萧嗣在三章击败任约', [('v163-y-550-p19', '鄱阳世子嗣与任约战于三章，约败走；嗣因徙镇三章')]),
        ('r06-war-550-changsha-fall', -550, ['war'], '王僧辩攻克长沙并杀萧誉', [('v163-y-550-p27', '王僧辩急攻长沙，辛巳，克之。执河东王誉，斩之')]),
        ('r06-war-550-xuyi', -550, ['war'], '徐嗣徽击退夜袭湓城的寻阳军', [('v163-y-550-p42', '寻阳王大心遣徐嗣徽夜袭湓城，安南侯恬、裴之横等击走之。')]),
        ('r06-disaster-famine-550-jiangnan', -550, ['disaster', 'famine'], '江南旱蝗造成大饥荒与大量死亡', [('v163-y-550-p22', '时江南连年旱蝗，江、扬尤甚，百姓流亡，相与入山谷、江湖，采草根、木叶，菱芡而食之，所在皆尽，死者蔽野。')]),
        ('r06-war-550-gan-shi', -550, ['war'], '洗氏击败李迁仕部将杜平虏，陈霸先攻退李迁仕', [('v163-y-550-p48', '洗氏袭击，大破之，迁仕走保宁都。文育亦击走平虏，据其城。')]),
        ('r06-war-550-xiangzhou-final', -550, ['war'], '王僧辩攻克长沙，萧誉被俘处死', [('v163-y-550-p27', '王僧辩急攻长沙，辛巳，克之。执河东王誉，斩之')]),
        ('r06-war-550-jingzhou-riots', -550, ['war'], '萧绎攻入郢州，萧纶退走并在齐昌收集部众', [('v163-y-550-p67', '僧辩入据郢州。'), ('v163-y-550-p68', '纶出营巴水，流民八九千人附之，稍收散卒，屯于齐昌。')]),
        ('r06-war-550-rengyue', -550, ['war'], '任约攻占西阳、武昌并击败邵陵王纶', [('v163-y-550-p73', '任约进寇西阳、武昌。'), ('v163-y-550-p73', '任约闻之，遣仪同叱罗子通等将铁骑二百袭之，纶不为备，策马亡走。'), ('v163-y-550-p73', '任约遂据西阳、武昌。')]),
        ('r06-war-550-beiji', -550, ['war'], '西魏军进攻北齐后因雨撤回蒲坂', [('v163-y-550-p85', '魏丞相泰自弘农为桥，济河，至建州。'), ('v163-y-550-p85', '会久雨，自秋及冬，魏军畜产多死，乃自蒲阪还。')]),
        ('r06-war-550-beijiang', -550, ['war'], '徐文盛在贝矶击败任约水军', [('v163-y-550-p86', '徐文盛军贝矶，任约帅水军逆战，文盛大破之，斩叱罗子通、赵威方')]),
        ('r06-war-550-xuan-cheng', -550, ['war'], '侯景攻克宣城，杨白华投降', [('v163-y-550-p90', '景自帅众讨杨白华于宣城，白华力屈而降')]),
        ('r06-war-551-yangzhou-revolt', -551, ['war'], '余孝顷起兵拒侯景，于庆攻之未克', [('v164-y-551-p0', '新吴余孝顷举兵拒侯景，景遣于庆攻之，不克。')]),
        ('r06-war-551-guangzhou', -551, ['war'], '陈霸先擒杀李迁仕', [('v164-y-551-p12', '李迁仕收众还击南康，陈霸先遣其将杜僧明等拒之，生擒迁仕，斩之。')]),
        ('r06-war-551-xiyang', -551, ['war'], '徐文盛在西阳击败侯景军，侯景败退', [('v164-y-551-p18', '壬寅，景军至西阳，与徐文盛夹江筑垒。癸卯，文盛击破之，射其右丞库狄式和，坠水死，景遁走还营。')]),
        ('r06-war-551-yingzhou', -551, ['war'], '侯景突袭攻陷郢州，徐文盛军溃退', [('v164-y-551-p20', '侯景闻江夏空虚，乙巳，使宋子仙、任约帅精骑四百，由淮内袭郢州。'), ('v164-y-551-p20', '子仙等已入城。'), ('v164-y-551-p20', '文盛众惧而溃，与长沙王韶等逃归江陵。')]),
        ('r06-war-551-baling-siege', -551, ['war'], '侯景军围攻巴陵，被王僧辩守军击退', [('v164-y-551-p22', '景肉薄百道攻城，城中鼓噪，矢石雨下，景士卒死者甚众，乃退。僧辩遣轻兵出战，凡十余返，皆捷。'), ('v164-y-551-p25', '侯景昼夜攻巴陵，不克，军中食尽，疾疫死伤太半。'), ('v164-y-551-p26', '僧佑、法和纵兵击之，约兵大溃，杀溺死者甚众，擒约送江陵。景闻之，乙巳，焚营宵遁。')]),
        ('r06-war-551-songzixian', -551, ['war'], '王僧辩攻取鲁山、郢州并擒杀宋子仙、丁和', [('v164-y-551-p27', '王僧辩至汉口，先攻鲁山，擒支化仁送江陵。辛酉，攻郢州，克其罗城，斩首千级。宋子仙退据金城，僧辩四面起土山，攻之。'), ('v164-y-551-p29', '子仙且战且走，至白杨浦，大破之，周铁虎生擒子仙及丁和，送江陵，杀之。')]),
        ('r06-war-551-yangjing', -551, ['war'], '萧绎攻克江州并击败任延和等守军', [('v164-y-551-p35', '王僧辩乘胜下湓城'), ('v164-y-551-p35', '任延和等弃城走。')]),
        ('r06-war-551-jiangdong', -551, ['war'], '刘神茂等在东阳起兵响应江陵，侯景军攻占建德', [('v164-y-551-p46', '司空、东道行台刘神茂闻侯景自巴丘败还，阴谋叛景，吴中士大夫咸劝之；乃与仪同三司尹思合、刘归义、王晔、云麾将军元頵等据东阳以应江陵'), ('v164-y-551-p53', '谢答仁、李庆绪攻建德，擒元頵、李占送建康')]),
        ('r06-war-551-songzixian-wujun', -551, ['war'], '宋子仙攻破吴郡并杀死苏单于', [('v164-y-551-p47', '侯景以赵伯超为东道行台，据钱塘；以田迁为军司，据富春；以李庆绪为中军都督，谢答仁为右厢都督，李遵为左厢都督，以讨刘神茂。')]),
        ('r06-war-552-turks', -552, ['war'], '突厥土门击败柔然，柔然可汗自杀', [('v164-y-552-p4', '突厥土门袭击柔然，大破之。柔然头兵可汗自杀')]),
        ('r06-war-552-houjing-counter', -552, ['war'], '王僧辩击败侯子鉴，西军进军建康', [('v164-y-552-p7', '王僧辩等至芜湖，侯景守将张黑弃城走。'), ('v164-y-552-p8', '大舰断其归路，鼓噪大呼，合战中江，子鉴大败，士卒赴水死者数千人。'), ('v164-y-552-p8', '景闻子鉴败，大惧，涕下覆面')]),
        ('r06-war-552-jiankang', -552, ['war'], '王僧辩、陈霸先击败侯景并收复建康', [('v164-y-552-p9', '僧辩问计于陈霸先，霸先曰：「前柳仲礼数十万兵隔水而坐，韦粲在青溪，竟不渡岸，贼登高望之，表里俱尽，故能覆我师徒。今围石头，须渡北岸。'), ('v164-y-552-p11', '景冲将军王僧志陈，僧志小缩，霸先遣将军安陆徐度将弩手二十横截其后，景兵乃却。霸先与王琳、杜龛等以铁骑乘之，僧辩以大兵继进，景兵败退，据其栅。'), ('v164-y-552-p11', '景与霸先殊死战，景帅百余骑，弃抬执刀，左右冲陈；陈不动，众遂大溃，诸军逐北至西明门。')]),
        ('r06-war-552-houjing-death', -552, ['war'], '侯瑱追击侯景于松江并擒杀其部将', [('v164-y-552-p26', '己酉，侯瑱追及景于松江，景犹有船二百艘，众数千人，瑱进击，败之，擒彭隽、田迁、房世贵、蔡寿乐、王伯丑。')]),
        ('r06-war-552-hanzhong', -552, ['war'], '西魏达奚武攻下上津、魏兴并迫降萧循', [('v164-y-552-p3', '魏将王雄取上津、魏兴，东梁州刺史安康李迁哲军败，降之。'), ('v164-y-552-p32', '杨干运至剑北，魏达奚武逆击之，大破干运于白马'), ('v164-y-552-p42', '循乃请降')]),
        ('r06-war-552-tangqiu', -552, ['war'], '陈霸先等击败齐军，解秦郡之围', [('v164-y-552-p40', '与元建大战于士林，大破之，斩首万余级，生擒千余人。')]),
        ('r06-war-552-guangling', -552, ['war'], '陈霸先围攻广陵，后应北齐议和撤军', [('v164-y-552-p46', '僧辩乃命武州刺史杜崱等助之。会盛等谋泄，霸先因进军围广陵。'), ('v164-y-552-p50', '齐主使告王僧辩、陈霸先曰：「请释广陵之围，必归广陵、历阳两城。」霸先引兵还京口')]),
        ('r06-war-552-wangna', -552, ['war'], '陆纳在渌口击败丁道贵，随后攻巴陵被萧循击退', [('v164-y-552-p60', '陆纳袭击衡州刺史丁道贵于渌口，破之。道贵奔零陵，其众悉降于纳。'), ('v164-y-552-p60', '纳乘水来攻，矢下如雨，循方食甘蔗，略无惧色，徐部分将士击之，获其一舰；纳退保长沙。')]),
        ('r06-war-553-shu-campaign', -553, ['war'], '西魏尉迟迥攻取安州、梁州并围成都，萧撝出降', [('v165-y-553-p10', '泰乃遣迥督开府仪同三司原珍等六军，甲士万二千，骑万匹，自散关伐蜀。'), ('v165-y-553-p14', '干运以州降。'), ('v165-y-553-p14', '迥使原珍等击走之。'), ('v165-y-553-p25', '魏尉迟泂围成都五旬，永丰侯撝屡出战，皆败，乃请降。')]),
        ('r06-war-553-wuling', -553, ['war'], '王琳等击败萧纪军，萧纪兵败被擒杀', [('v165-y-553-p23', '谢答仁、任约进攻侯叡，破之，拔其三垒。'), ('v165-y-553-p23', '纪众大溃，赴水死者八千余人，猛围而守之。'), ('v165-y-553-p23', '猛引兵至纪所，纪在舟中绕床而走，以金囊掷猛曰：「以此雇卿，送我一见七官。」猛曰：「天子何由可见！杀足下，金将安之！」遂斩纪及其幼子圆满。')]),
        ('r06-war-553-dongguan', -553, ['war'], '侯瑱在东关击败北齐郭元建军', [('v165-y-553-p34', '南豫州刺史侯瑱与郭元建战于东关，齐师大败，溺死者万计。')]),
        ('r06-war-553-khitan', -553, ['war'], '高洋长途奔袭击败契丹并俘获大量人口牲畜', [('v165-y-553-p31', '甲辰，与契丹遇，奋击，大破之，虏获十余万口，杂畜数百万头。潘相乐又于青山破契丹别部。')]),
        ('r06-war-554-shanhu', -554, ['war'], '高洋联合诸路军击败山胡并攻取石楼', [('v165-y-554-p0', '齐主自离石道讨山胡，遣斛律金从显州道，常山王演从晋州道夹攻，大破之，男子十三以上皆斩，女子及幼弱以赏军，遂平右楼。')]),
        ('r06-war-554-suyu', -554, ['war'], '杜僧明击败围攻宿预的北齐军', [('v165-y-554-p1', '陈霸先自丹徒济江，围齐广陵'), ('v165-y-554-p6', '齐将王球攻宿预，杜僧明出击，大破之，球归彭城。')]),
        ('r06-war-554-rouran', -554, ['war'], '高洋击败柔然并俘获其部众', [('v165-y-554-p11', '柔然披靡，因溃围而出。柔然走，追击之，伏尸二十余里，获庵罗辰妻子，虏三万余口'), ('v165-y-554-p14', '齐主复自击柔然，大破之。')]),
        ('r06-war-554-eastwei-pingzhou', -554, ['war'], '齐军击退尹令思并击败严超达，解除广陵围困', [('v165-y-554-p20', '令思不意齐师猝至，望风退走。韶进击超达，破之，回趣广陵，陈霸先解围走。')]),
        ('r06-war-554-jiangling', -554, ['war'], '西魏于谨等围攻并攻陷江陵，梁元帝出降', [('v165-y-554-p32', '魏遣柱国常山公于谨、中山公宇文护、大将军杨忠将兵五万入寇，冬，十月，壬戌，发长安。'), ('v165-y-554-p36', '癸未，魏军济汉，于谨令宇文护、杨忠帅精骑先据江津，断东路。'), ('v165-y-554-p40', '甲寅，魏人百道攻城，城中负户蒙楯，胡僧佑亲当矢石，昼夜督战，奖励将士，明行赏罚，众咸致死，所向摧殄，魏不得前。俄而僧佑中流矢死，内外大骇。魏悉众攻栅，反者开西门纳魏师'), ('v165-y-554-p41', '帝遂去羽仪文物，白马素衣出东门')]),
        ('r06-war-554-rouran-west', -554, ['war'], '柔然乙旃达官进犯广武，被李弼击退', [('v165-y-554-p17', '柔然乙旃达官寇魏广武，柱国李弼遣击，破之。')]),
        ('r06-war-555-jiangling', -555, ['war'], '王琳等与北齐争夺江陵，陆法和及宋莅举郢州降齐', [('v166-y-555-p3', '齐主使清河王岳将兵攻安州，以救江陵。岳至义阳，江陵陷，因进军临江，郢州刺史陆法和及仪同三司宋莅举州降之')]),
        ('r06-war-555-dongguan', -555, ['war'], '北齐攻克东关并斩杀裴之横，王僧辩被迫纳萧渊明', [('v166-y-555-p9', '丙戌，齐克东关，斩裴之横，俘数千人；王僧辩大惧，出屯姑孰，谋纳渊明。')]),
        ('r06-war-555-chenbaixian', -555, ['war'], '陈霸先袭取石头城并杀王僧辩父子', [('v166-y-555-p25', '霸先因是留旰于京口，举兵袭僧辩。'), ('v166-y-555-p26', '石头城北接冈阜，不甚危峻，安都被甲带长刀，军人捧之，投于女垣内，众随而入，进及僧辩卧室；霸先兵亦自南门入。'), ('v166-y-555-p26', '是夜，霸先缢杀僧辩父子。')]),
        ('r06-war-555-chenopposition', -555, ['war'], '陈霸先平定杜龛等地方反抗势力', [('v166-y-555-p31', '龛据吴兴拒霸先'), ('v166-y-555-p31', '蒨言笑自若，部分益明，众心乃定。泰昼夜苦攻，数旬，不克而退。'), ('v166-y-555-p33', '载及杜北叟皆降'), ('v166-y-555-p34', '忌入据吴郡')]),
        ('r06-war-556-dukan-execution', -556, ['war'], '陈蒨处决杜龛', [('v166-y-556-p2', '蒨遣人负出，于项王寺前斩之。')]),
        ('r06-war-555-qiship', -555, ['war'], '北齐军渡江占据姑孰、石头，陈霸先烧毁齐军船只', [('v166-y-555-p35', '齐遣兵五千渡江据姑孰，以应徐嗣徽、任约。'), ('v166-y-555-p35', '侯安都夜袭胡墅，烧齐船千余艘')]),
        ('r06-war-555-qidefeat', -555, ['war'], '陈霸先击败北齐及徐嗣徽、任约部队', [('v166-y-555-p41', '霸先督兵疾战，纵火烧栅，齐兵大败，争舟相挤，溺水者以千数，呼声震天地，尽收其船舰。'), ('v166-y-555-p42', '霸先陈兵石头南门，送齐人归北，徐嗣徽、任约皆奔齐。')]),
        ('r06-war-555-gushu-rebels', -555, ['war'], '侯安都击败并驱逐在姑孰起兵的陈嗣、曹朗', [('v166-y-555-p43', '江宁令陈嗣、黄门侍郎曹朗据姑孰反，霸先命侯安都等讨平之。')]),
        ('r06-war-556-guangling', -556, ['war'], '北齐军围攻梁山、进逼建康，陈霸先击退齐军并擒获徐嗣徽', [('v166-y-556-p8', '齐遣仪同三司萧轨、库狄伏连、尧难宗、东方老等与任约、徐嗣徽合兵十万入寇，出栅口，向梁山。陈霸先帐内荡主黄丛逆击，破之，齐师退保芜湖。'), ('v166-y-556-p16', '安都帅十二骑突其陈，破之，生擒齐仪同三司乞伏无劳。'), ('v166-y-556-p18', '纵兵大战，安都自白下引兵横出其后，齐师大溃，斩获数千人，相蹂践而死者不可胜计，生擒徐嗣徽及弟嗣宗，斩之以徇')]),
        ('r06-war-555-houan-du', -555, ['war'], '侯安都夜袭攻破秦郡齐军营栅', [('v166-y-555-p41', '侯安都袭秦郡，破徐嗣徽栅，俘数百人。')]),
        ('r06-war-556-wei-suppress', -556, ['war'], '西魏陆腾攻破山城，平定陵州叛獠', [('v166-y-556-p40', '魏江州刺史陆腾讨陵州叛獠，獠因山为城，攻之难拔。腾乃陈伎乐于城下一面，獠弃兵，携妻子临城观之，腾潜师三面俱上，斩首万五千级，遂平之。')]),
        ('r06-war-556-tu-yugu', -556, ['war'], '突厥与西魏联兵击败吐谷浑并俘获其王妻子', [('v166-y-556-p43', '木杆破贺真，获夸吕妻子；宁破树敦，虏征南王')]),
        ('r06-war-556-hou-ping', -556, ['war'], '侯平在豫章击败侯瑱守军，侯瑱随后归降陈霸先', [('v166-y-556-p33', '侯平发兵攻奫，大掠豫章，焚之，奔于建康。瑱众溃，奔湓城，依其将焦僧度。僧度劝之奔齐，会霸先使记济阳蔡景历南上，说瑱令降，瑱乃诣阙归罪')]),
        ('r06-war-557-xinyu', -557, ['war'], '陈法武、谭世远在南康起兵杀死萧勃', [('v167-y-557-p16', '德州刺史陈法武、前衡州刺史谭世远攻勃，杀之。')]),
        ('r06-war-557-lingnan', -557, ['war'], '侯安都、周文育平定萧孜、余孝顷余部并收复岭南', [('v167-y-557-p23', '安都潜师夜烧其船舰，文育帅水军、安都帅步军进攻之；萧孜出降，孝顷逃归新吴，文育等引兵还。'), ('v167-y-557-p23', '頠至岭南，诸郡皆降，遂克广州，岭南悉平。')]),
        ('r06-war-557-wanglin', -557, ['war'], '王琳击败陈朝侯安都、周文育军并俘获诸将', [('v167-y-557-p26', '霸先以开府仪同三司侯安都为西道都督，周文育为南道都督，将舟师二万会武二万会武昌以击之。'), ('v167-y-557-p46', '安都据西岸，相持数日，乃合战，安都等大败。安都、文育乃裨将徐敬成、周鎑虎、程灵洗皆为琳所擒')]),
        ('r06-war-557-qiaoyan', -557, ['war'], '北周军击败并杀死谯淹，俘获其部众', [('v167-y-557-p49', '谯淹帅水军七千、老弱三万自蜀江东下，欲就王琳，周使开府仪同三司贺若敦、叱罗晖等击之，斩淹，悉俘其众。')]),
        ('r06-war-558-simaxiaonan', -558, ['war'], '达奚武、杨忠率军入齐境接应司马消难归西魏', [('v167-y-558-p9', '消难惧，密令所亲中兵参军裴藻托以私假，间行人关，请降于周。'), ('v167-y-558-p10', '武亲来，麾数百骑西去，忠勒余骑不动，俟门开而入，驰遣召武。'), ('v167-y-558-p10', '乃徐引还。武叹曰：「达奚武自谓天下健儿，今日服矣！」')]),
        ('r06-war-558-zhou-di', -558, ['war'], '黄法氍、沈恪、周敷救援周迪，击溃余孝顷军', [('v167-y-558-p19', '余孝顷等屯二万军于工塘，连八城以逼周迪。'), ('v167-y-558-p28', '孝顷等皆弃舟引兵步走，迪追击，尽擒之')]),
        ('r06-war-558-wanglin-conflict', -558, ['war'], '王琳与鲁悉达争夺江道，陈朝军队进击未克后撤', [('v167-y-558-p0', '沈泰袭之，不克。'), ('v167-y-558-p33', '周文育、侯安都、徐敬成许王子晋以厚赂，子晋及伪以小船依鵺而钓，夜，戴之上岸，入深草中，步投陈军')]),
        ('r06-war-558-houxiang', -558, ['war'], '侯瑱、徐度率水师讨伐王琳', [('v167-y-558-p25', '诏司空侯瑱与领军将军徐度帅舟师为前军以讨王琳。')]),
        ('r06-war-559-qi', -559, ['war'], '侯瑱在合肥焚毁北齐战船', [('v167-y-559-p2', '侯瑱引兵焚齐舟舰于合肥。')]),
        ('r06-war-559-baili', -559, ['war'], '北齐斛律光击败曹回公并攻取文侯镇', [('v167-y-559-p4', '齐斛律光将骑一万击周开府仪同三司曹回公，斩之，柏谷城主薛禹生弃城走，遂取文侯镇')]),
        ('r06-war-559-tu-yugu', -559, ['war'], '贺兰祥击败吐谷浑并攻取洮阳、洪和', [('v167-y-559-p16', '周贺兰祥与吐谷浑战，破之，拔其洮阳、洪和二城，以其地为洮州。')]),
        ('r06-war-559-wanglin-east', -559, ['war'], '王琳率军东下，陈朝军队抵御，吴明彻遇袭败退', [('v167-y-559-p42', '王琳闻高祖殂，乃以少府卿吴郡孙玚为郢州刺史，总留任，奉梁永嘉王庄出屯濡须口'), ('v167-y-559-p42', '安州刺史吴明彻夜袭湓城，琳遣巴陵太守任忠击明彻，大破之，明彻仅以身免。')]),
        ('r06-war-559-weny u', -559, ['war'], '周文育等讨伐余公扬，后被熊昙朗杀害', [('v167-y-559-p19', '文育军于金口，公扬诈降，谋执文育，文育觉之，囚送建康。'), ('v167-y-559-p19', '文育不从。时周迪弃船走，不知所在，乙酉，文育得迪书，自赍以示昙朗，昙朗杀之于坐而并其众')]),
        ('r06-war-560-wanglin', -560, ['war'], '侯瑱在芜湖击败王琳与北齐联军，王琳败逃北齐', [('v168-y-560-p7', '瑱进军虎槛洲，琳亦出船列于江西，隔洲而泊。明日，合战，琳军少却，退保西岸。'), ('v168-y-560-p9', '瑱发拍以击琳舰，又以牛皮肥蒙冲小船以触其舰，并镕铁洒之。琳军大败，军士溺死者什二三，余皆弃船登岸，为陈军所杀殆尽。齐步军在西岸者，自相蹂践，并陷于芦荻泥淖中；骑皆弃马脱走，得免者什二三。擒刘伯球、慕容子会，斩获万计，尽收梁、齐军资器械。'), ('v168-y-560-p9', '琳乘舴艋冒陈走，至湓城，欲收合离散，众无附者，乃与妻妾左右十余人奔齐。')]),
        ('r06-war-560-xiongdamang', -560, ['war'], '周迪等击破熊昙朗并收复其城', [('v168-y-560-p38', '琳败，昙朗部众离心，迪攻拔其城，虏男女万余口。昙朗走入村中，村民斩之')]),
        ('r06-war-560-yingzhou', -560, ['war'], '北周围攻郢州未克，孙玚坚守后归降陈朝', [('v168-y-560-p37', '周人起土山，长梯昼夜攻之，因风纵火，烧其内城南面五十余楼。孙玚兵不汉千人，身自抚循，行酒赋食，士卒皆为之死战。周人不能克'), ('v168-y-560-p37', '遂遣使奉表，举中流之地来降。')]),
        ('r06-war-560-xiangzhou', -560, ['war'], '贺若敦率周军救援湘州，与侯瑱相持', [('v168-y-560-p63', '太尉侯瑱等将兵逼湘州。贺若敦将步骑救之，乘胜深入，军于湘川。'), ('v168-y-560-p66', '瑱袭破独孤盛于杨叶洲，盛收兵登岸，筑城自保。')]),
        ('r06-war-560-wuling', -560, ['war'], '贺若敦率军攻取武陵，吴明彻退守巴陵', [('v168-y-560-p62', '周军司马贺若敦，帅众一万，奄至武陵；武州刺史吴明彻不能拒，引军还巴陵。')]),
        ('r06-war-562-zhou-di-campaign', -562, ['war'], '侯安都攻破留异营垒，留异逃奔晋安', [('v168-y-562-p21', '留异始谓台军必自钱塘上，既而侯安都步由诸暨出永康，异大惊，奔桃枝岭，于岩口竖栅以拒之。'), ('v168-y-562-p21', '安都引船入堰，起楼舰与异城等，发拍碎其楼堞。异与其子忠臣脱身奔晋安，依陈宝应。')]),
        ('r06-war-562-xinan', -562, ['war'], '程文季攻下向文政据守的新安', [('v168-y-562-p22', '文政战败，遂降。')]),
        ('r06-war-562-gaoguiyan', -562, ['war'], '段韶、娄叡攻破高归彦据守的信都城', [('v168-y-562-p30', '大司马段韶、司空娄叡讨之。归彦于南境置私驿，闻大军将至，即闭城拒守。'), ('v168-y-562-p31', '既而城破，单骑走，至交津，获之，销送邺。')]),
        ('r06-war-562-zhou-di', -562, ['war'], '吴明彻讨伐周迪未克，陈顼接替统军', [('v168-y-562-p19', '以安右将军吴明彻为江州刺史，督高州刺史黄法鳓、豫章太守周敷共讨周迪。'), ('v168-y-562-p38', '吴月彻至临川攻周迪，不能克。丁亥，诏安成王顼代之。')]),
        ('r06-war-563-zhou-di', -563, ['war'], '章昭达击败周迪，周迪逃往晋安', [('v169-y-563-p25', '周迪复越东兴岭为寇，辛未，诏护军章昭达将兵讨之。'), ('v169-y-563-p29', '章昭达大破周迪。迪脱身潜窜山谷')]),
        ('r06-war-563-zhouqi-alliances', -563, ['war'], '北周与突厥结盟并分道伐齐', [('v169-y-563-p27', '周人欲与突厥木杆可汗连兵伐齐'), ('v169-y-563-p28', '遣忠将步骑一万，与突厥自北道伐齐，又遣大将军达奚武帅步骑三万，自南道出平阳，期会于晋阳。'), ('v169-y-563-p34', '周杨忠拔齐二十余城。齐人守陉岭之隘，忠击破之。')]),
        ('r06-war-564-jinyang', -564, ['war'], '段韶击败周军与突厥联军，迫使其退兵', [('v169-y-564-p1', '齐悉其锐师鼓噪而出。突厥震骇，引上西山，不肯战，周师大败而还。'), ('v169-y-564-p1', '突厥引兵出塞，纵兵大掠')]),
        ('r06-disaster-famine-564-shandong', -564, ['disaster', 'famine'], '山东大水引发严重饥荒', [('v169-y-564-p53', '是岁，齐山东大水，饥死者不可胜计。')]),
        ('r06-war-564-zhouliang-expedition', -564, ['war'], '宇文护率周军大举攻齐，尉迟迥围攻洛阳并攻下悬瓠', [('v169-y-564-p32', '征二十四军及左右厢散隶秦、陇、巴、蜀之兵并羌、胡内附者，凡二十万人。'), ('v169-y-564-p33', '护军至潼关，遣柱国尉迟迥帅精兵十万为前锋，趣洛阳'), ('v169-y-564-p38', '尉迟迥围洛阳'), ('v169-y-564-p41', '权景宣围悬瓠，十二月，齐豫州道行台．豫州刺史太原王士良、永州刺史萧世怡并以城降之。')]),
        ('r06-war-564-mangshan', -564, ['war'], '北齐段韶率军击败北周，周军围洛阳后撤退', [('v169-y-564-p45', '韶至洛阳，帅帐下三百骑，与诸将登邙阪，观，周军形势。'), ('v169-y-564-p46', '周师大败，一时瓦解，投坠溪谷死者甚众。'), ('v169-y-564-p47', '周师在城下者亦解围遁去，委弃营幕'), ('v169-y-564-p49', '至夜，收军，宪欲待明更战。达奚武曰：「洛阳军散，人情震骇，若不因迄速还，明日欲归不得。')]),
        ('r06-war-564-chenbao', -564, ['war'], '章昭达击败陈宝应军，擒获陈宝应与留异', [('v169-y-564-p36', '昭达放筏冲宝应水栅，尽坏之，又出兵攻其步军。方合战，上遣将军余孝顷自海道适至，并力乘之。十一月，己丑，宝应大败，逃至莆口'), ('v169-y-564-p36', '昭达追擒之，并擒留异及其族党，送建康，斩之。')]),
        ('r06-war-565-zhou-di', -565, ['war'], '程灵洗击败周迪并将其擒杀', [('v169-y-565-p18', '上遣都督程灵洗自鄱阳别道击周迪，破之。'), ('v169-y-565-p18', '其人诱迪出猎，勇士伏于道傍，出斩之。丙戌，传首至建康。')]),
        ('r06-war-566-wuling', -566, ['war'], '陆腾攻破水逻、石墨、双城，平定巴蜀蛮人叛乱', [('v169-y-566-p27', '乃还王亮帅众渡江，旬日，拔其八城'), ('v169-y-566-p27', '水逻众溃，斩首万余级，捕虏万余口。令贤走，追获，斩之。'), ('v169-y-566-p28', '进击，皆擒之，尽斩诸向酋长，捕虏万余口。')]),
        ('r06-war-566-wanrong', -566, ['war'], '辛昂出兵击溃围攻万荣郡城的叛军', [('v169-y-566-p30', '倍道兼行，出其不意，直趣贼垒。贼以为爻军至，望风瓦解，一郡获全。')]),
        ('r06-war-567-chen-coup', -567, ['war'], '陈顼拘捕到仲举、韩子高等人并赐死', [('v170-y-567-p11', '平旦，仲举、子高入省，皆执之，并郁送廷尉，下诏，于狱赐死')]),
        ('r06-war-567-huajiao', -567, ['war'], '华皎引周、梁联军叛陈，吴明彻等在沌口击溃联军', [('v170-y-567-p16', '皎遣使潜引周兵，又自归于梁，以其子玄响为质。'), ('v170-y-567-p19', '司徒顼遣吴明彻帅舟师三万趣郢州'), ('v170-y-567-p31', '皎自巴陵与周、梁水军顺流簌风而下，军势甚盛，战于沌口。量、明彻募军中小舰，多赏金银，令先出当西军大舰受其拍；西军诸舰发拍皆尽，然后量等以大舰拍之，西转，自焚，西军大败。皎与戴僧朔单舸走，过巴陵，不敢发岸，径奔江陵；卫公直亦奔江陵。')]),
        ('r06-war-567-yuanding', -567, ['war'], '徐度诱降并俘获北周元定军', [('v170-y-567-p32', '定信之，解仗就度，度执之，尽俘其众，并擒梁大将军李广。定愤恚而卒。')]),
        ('r06-war-567-xiangzhou', -567, ['war'], '吴明彻攻取后梁河东郡', [('v170-y-567-p34', '吴明彻乘胜攻梁河东，拔庂。')]),
        ('r06-war-567-mianzhou', -567, ['war'], '程灵洗攻陷北周沔州并擒获刺史裴宽', [('v170-y-567-p36', '程灵洗舟师奄至城下。会大两，水暴涨，灵洗引大舰临城城发拍，击楼堞皆碎，矢石昼夜攻之三十余日；陈人登城，宽犹帅众执短兵拒战；又二日，乃擒之。')]),
        ('r06-war-568-jiangling', -568, ['war'], '吴明彻进攻江陵，被后梁守军击退', [('v170-y-568-p8', '吴明彻乘胜进攻江陵，引水灌之。梁主出顿纪南以避之。周总管田弘从梁主副总管高琳与梁仆射王操守江陵三城，昼夜拒战十旬。梁将马武、吉彻击明彻，败之。明彻退保公安，梁主乃得还。')]),
        ('r06-war-568-zhou-hengling', -568, ['war'], '北周赵文表平定恒棱獠人叛乱', [('v170-y-568-p31', '乃引兵自险路入。乘高而望、果有伏兵。獠既失计，争帅众来降。文表皆慰抚之，仍征其租税，无敢违者。')]),
        ('r06-war-569-yiyang-forts', -569, ['war'], '北周在宜阳修筑崇德等五城', [('v170-y-569-p25', '九月，辛卯，周遣齐公宪与柱国李穆将兵趣宜阳，筑崇德等五城。')]),
        ('r06-war-570-yiyang-battle', -570, ['war'], '斛律光援救宜阳并击败北周军', [('v170-y-570-p4', '齐太傅斛律光，将步骑三万救宜阳，屡破周军，筑统关、丰化二城而还。周军追之，光纵击，又破之')]),
        ('r06-war-569-ouyanghe', -569, ['war'], '欧阳纥起兵反陈并攻衡州，章昭达随后奉命讨伐', [('v170-y-569-p26', '纥恐惧，其下多劝之反，遂举兵攻衡州刺史钱道戢。'), ('v170-y-569-p27', '帝遣中书侍郎徐俭持节谕旨。'), ('v170-y-569-p28', '诏车骑将军音昭达讨纥。')]),
        ('r06-war-570-ouyanghe', -570, ['war'], '章昭达击败并擒杀欧阳纥', [('v170-y-570-p6', '纥众大败，生擒纥，送之；癸未，斩于建康市。')]),
        ('r06-war-570-jiangling', -570, ['war'], '陈军攻破后梁安蜀城并击退周军援兵', [('v170-y-570-p25', '昭达命军士为长戟，施于楼船上，仰割其索。索断，粮绝，因纵兵攻安蜀城，下之。'), ('v170-y-570-p26', '迁哲与陆胜力战拒之，乃退。')]),
        ('r06-war-571-yang', -571, ['war'], '段韶攻陷定阳城并俘获北周守将', [('v170-y-571-p13', '韶围定阳城，周韶卧病，谓兰陵王长恭曰：「此城三面重涧，皆无走路；唯虑东南一道耳，贼必从此出。宜简精兵专守之，此必成擒。」'), ('v170-y-571-p13', '敷帅见兵突围夜走，伏兵击擒之，尽俘其众。')]),
        ('r06-war-573-luliang', -573, ['war'], '陈军在吕梁击败北齐军，萧摩诃斩杀齐军勇士', [('v171-y-573-p20', '辛酉，战于吕梁。将战，吴明彻谓巴山太守萧摩诃曰：「若殪此胡，则彼军夺气，君才不减关羽矣。」摩诃曰：「愿示其状，当为公取之。」明彻乃召降人有识胡者，使指示之，自酌酒以饮摩诃。摩诃饮毕，驰马冲齐军。胡挺身出陈十余步，壳弓未发，摩诃遥掷铣鋧，正中其额，应手而仆。齐军大力十余人出战，摩诃又斩之。于是齐军大败，尉破胡走，长孙洪略战死。'), ('v171-y-573-p21', '破胡之出师也，齐人使侍中王琳与之俱。琳谓破胡曰：「吴兵甚锐，宜以长策制之，慎勿轻鬬！」破胡不从而败。琳单骑仅免')]),
        ('r06-war-573-luyang-cities', -573, ['war'], '陈军攻取石梁、瓦梁、庐江、历阳与合肥等城', [('v171-y-573-p22', '甲子，南谯太守徐槾克石梁城。五月，己巳，瓦梁城降。癸酉，阳平郡降。甲戌，徐槾克庐江城。历阳窘蹙乞降，黄法鳓缓之，则又拒守。法鳓鳓，帅卒急攻，丙子，克之，尽杀戍卒。进军合肥，合肥望旗请降，法鳓禁侵掠，抚劳戍卒，与之盟而纵之。')]),
        ('r06-war-573-northern-cities', -573, ['war'], '陈军连续攻取北齐高唐、齐昌、东关、蕲、谯等城', [('v171-y-573-p24', '己卯，齐北高唐郡降。辛巳，诏南豫州刺史黄法鳓徙镇历阳。乙酉，南齐昌太守黄咏克齐昌外城。丙戌，庐陵内史任忠军于东关，克其东、西二城，进克蕲城；戊子，又克谯郡城。秦州城降。癸巳，瓜步、胡墅二城降。')]),
        ('r06-war-573-pingzhou', -573, ['war'], '陈军攻克泾州、新蔡与合州、仁州', [('v171-y-573-p32', '癸丑，程文季攻齐泾州，拔之。乙卯，宣毅司马湛陀克新蔡城。'), ('v171-y-573-p34', '癸亥，黄法鳓克合州。吴明彻进攻仁州，甲子，克之。')]),
        ('r06-war-573-qichang-relief', -573, ['war'], '周炅设伏大败北齐援军陆骞部，陈军占据巴州等地', [('v171-y-573-p36', '齐遣尚书左丞陆骞将兵二万救齐昌，出自巴、蕲，遇西阳太守汝南周炅。炅留羸弱，设疑兵以当之，身帅精锐，由间道游其后，大破之。己巳，征北大将军吴明彻军至峡口，克其北岸城；南岸守者弃城走。周炅克巴州。淮北、绛城及谷阳士民，并杀其戍主，以城降。')]),
        ('r06-war-573-shouyang-outer', -573, ['war'], '吴明彻夜袭寿阳外郭，王琳部退守内城', [('v171-y-573-p37', '齐巴陵王王琳与扬州刺史王贵显保寿阳外郭，吴明彻以琳初入，众心未固，丙戌，乘夜攻之，城溃。齐兵退据相国城及金城。')]),
        ('r06-war-573-city-surrenders', -573, ['war'], '陈军攻取山阳、盱眙、海安、东海、晋州、阳平、马头、齐安与广陵楚子城', [('v171-y-573-p38', '八月，乙未，山阳城降。壬寅，盱眙城降。壬子，戎昭将军徐敬辩克海安城。青州东海城降。戊午，平固侯敬泰等克晋州。九月，甲子，阳平城降，王申，高阳太守沈善庆克马头城。甲戌，齐安城降。丙子，左卫将军樊毅克广陵楚子城。')]),
        ('r06-war-573-shouyang', -573, ['war'], '吴明彻筑堰灌寿阳并攻陷城池，俘获王琳等守将', [('v171-y-573-p48', '吴明彻攻寿阳，堰肥水以灌城，城中多病肿泄，死者什六七。齐行台右仆射琅邪皮景和等救寿阳，以尉破胡新败，怯懦不敢前，屯于淮口，敕使屡促之。然始渡淮，众数十万，去寿阳三十里，顿军不进。诸将皆惧，曰：「坚城未拔，大援在近，将若之何﹖」明彻曰：「兵贵神速，而彼结营不进，自挫其锋，吾知其不敢战，明矣。」乙巳，躬擐甲冑，四面疾攻，一鼓拔之，生擒王琳、王贵显、卢潜及扶风王可朱浑道裕、尚书左丞李騊余送建康。景和北遁，尽数其驼马辎重。')]),
        ('r06-war-573-yingkou', -573, ['war'], '樊毅击退北齐军对颍口的进攻', [('v171-y-573-p51', '丁未，齐遣兵万人至颍口，樊毅击走之。辛亥，遣兵援苍陵，又破之。')]),
        ('r06-war-573-qichang-jinan', -573, ['war'], '陈军攻克齐昌、淮阴、朐山、济阴与济南等地', [('v171-y-573-p53', '戊午，湛陀克齐昌城。十一月，甲戌，淮阴城降。庚辰，威虏将军刘桃枝克朐山城。辛巳，樊毅克济阴城。己丑，鲁广达攻济南徐州，克之；以广达为北徐州刺史，镇其地。')]),
        ('r06-war-573-north-xuzhou', -573, ['war'], '祖珽击退围逼北徐州的叛军', [('v171-y-573-p54', '齐北徐州民多起兵以应陈，逼其州城，祖珽命不闭城门，禁人不得出衢路，城中寂然。反者不测其故，疑人走城空，不设备。珽忽令鼓噪震天，反者皆惊走。既而复结陈向城，珽令录事参军王君植将兵拒之，自乘马临陈左右射。反者先闻其盲，谓其必不能出，忽见之，大惊。穆提婆欲令城陷，不遣援兵，珽且战且守，十余日，反者竟散走。')]),
        ('r06-war-573-jiangbei', -573, ['war'], '周炅讨伐田龙升叛乱并收复江北六州七镇', [('v171-y-573-p60', '龙升以江北六州、七镇叛入于齐，齐遣历阳王景安将兵应之。齐遣历阳王景安将兵应之。诏以炅为江北道大都督，总众军以讨龙升，斩之。景安退走，尽复江北之地。')]),
        ('r06-war-574-sihehao', -574, ['war'], '高思好起兵反齐，兵败投水身亡', [('v171-y-574-p8', '齐朔州行台南安王思好，本高氏养子，骁勇，得边镇人心。齐主使嬖臣斫骨光弁至州，光弁不礼于思好，思好怒，遂反，云欲入除君侧之恶」。进军至阳曲，自号大丞相。武卫将军赵海在晋阳，苍猝不暇奏，矫诏发兵拒之。矫诏发兵拒之。帝闻变，使尚书令唐邕等驰之晋阳，辛丑，帝勒兵继进。未至，思好军败，投水死。其麾下二千人，刘桃枝围之，且杀且招，终不降，以至于尽。')]),
        ('r06-war-575-tongzhou', -575, ['war'], '樊毅攻克潼州', [('v172-y-575-p2', '乙亥，左卫将军樊毅克潼州。')]),
        ('r06-war-575-heyang-campaign', -575, ['war'], '周军攻取河阴大城与武济，并围攻洛口、河阳中潬等城', [('v172-y-575-p30', '丁未，周主攻河阴大城，拔之。齐王宪拔武济；')]),
        ('r06-war-575-wu-luliang', -575, ['war'], '吴明彻在吕梁击败齐军数万人', [('v172-y-575-p35', '闰月，车骑大将军吴明彻将兵击齐彭城；壬辰，败齐兵数万于吕梁。')]),
        ('r06-war-576-jinzhou', -576, ['war'], '周军攻陷晋州，俘虏齐守将尉相贵及甲士八千', [('v172-y-576-p32', '遣内史王谊监诸军攻平阳城。齐行台仆射海昌王尉相贵婴城拒守。甲子，齐集兵晋祠。庚午，齐主自晋阳帅诸军趣晋州。周主日自汾曲至城下督战，城中窘急。庚午，行台左丞侯子钦出降于周。壬申，晋晋州刺史崔景嵩守北城，夜，遣使请降于周，王轨帅众应之。未明，周将北海段文振，杖槊与数十人先登，与景嵩同至尉相贵所，拔佩刀劫之。城上鼓噪，齐兵大溃，遂克晋州，虏相贵及甲士八千人。')]),
        ('r06-war-576-hongdong-yongan', -576, ['war'], '周齐王宪攻取洪洞、永安二城', [('v172-y-576-p34', '周齐王宪攻拔洪洞、永安二城，更图进取。齐人焚桥守险，军不得进，乃屯永安。')]),
        ('r06-war-576-chicken-ridge', -576, ['war'], '周军在鸡栖原击退齐军', [('v172-y-576-p35', '癸酉，齐主分军万人向千里径，又分军出汾水关，自帅大军上鸡栖原。宇文盛遣人告急，齐王宪自救之。齐师退，盛追击，破之。俄而椿告齐师稍逼，宪复还救之。与齐对陈，至夜不战。')]),
        ('r06-war-576-pingyang-siege', -576, ['war'], '齐军围攻平阳，周军守城并修复被攻破的城墙', [('v172-y-576-p39', '齐师遂围平阳，昼夜攻之。城中危急，楼堞皆尽，所存之城，寻仞而已。或短兵相接，或交马出入，外援不至，众皆震惧。梁士彦媖慨自若，谓将士曰：「死在今日，吾为尔先。」于是勇烈齐奋，呼声动地，无不一当百。齐师少却，乃令妻妾、军民、妇女，昼夜修城，三日而就。周主使齐王宪将兵六万屯涑川，遥为平阳声援。齐人作地道攻平阳，城陷十余步，将士乘势欲入。')]),
        ('r06-war-576-pingyang-battle', -576, ['war'], '周军在平阳击溃齐军，齐军伤亡万余并弃置辎重', [('v172-y-576-p41', '周主欲薄齐师，碍堑而止，自旦至申，相持不决。'), ('v172-y-576-p42', '于是填堑南引。周主大喜，勒诸军击之。'), ('v172-y-576-p43', '齐师大溃，死者万余人，军资器械，数百里间，委弃山积。')]),
        ('r06-war-576-luonu-fort', -576, ['war'], '周齐王宪攻取洛女砦，高阿那肱弃高壁退走', [('v172-y-576-p48', '周主引军向高壁，阿那肱望风退走。齐王宪攻洛女砦，拔之。')]),
        ('r06-war-576-jinyang', -576, ['war'], '周军攻入晋阳，安德王延宗率军反击并一度击退周军', [('v172-y-576-p54', '周师围晋阳，四合如黑云。安德王延宗命莫多娄敬显、韩骨胡拒城南，和阿干子、段畅城东，自帅众拒齐王宪于城北。延宗素肥，前如偃，后如伏，人常笑之。至是，奋大抬往来督战，劲捷若飞，所向无前。和阿干子、段畅以千骑奔周军。周主攻东门，际昏，遂入之，进焚佛寺。延宗、敬显自门入，夹击之，周师大乱，争门，相填压，寒路不得进。齐人从后斫刺，死者二千余人。')]),
        ('r06-war-576-jinyang-fall', -576, ['war'], '周军再攻晋阳并俘获安德王延宗，唐邕等齐将投降', [('v172-y-576-p55', '辛酉，旦，还攻东门，克之。延宗战力屈，走至城北，周人擒之。周主下马执其手，延宗辞曰：「死人手，何敢迫至尊！」周主曰：「两国天子，非有怨恶，直为百姓来耳。终不相害，勿怖也。」使复衣帽而礼之。唐邕等皆降于周。')]),
        ('r06-war-577-ye-fall', -577, ['war'], '周军围攻并攻陷北齐首都邺城', [('v173-y-577-p4', '壬辰，周师至邺城下；癸巳，围之，烧城西门。齐人出战，周师奋击，大破之。'), ('v173-y-577-p5', '周师入邺，齐王、公以下皆降。三藏犹拒战')]),
        ('r06-war-577-xindu', -577, ['war'], '北周齐王宪击败任城王湝、广宁王孝珩军并俘获二王', [('v173-y-577-p19', '宪至信都，湝陈于城南以拒之。湝所署领军尉相愿诈出略陈，遂以众降。相愿，湝心腹也，众皆骇惧。湝杀相愿妻子。明日，复战，宪击破之，俘斩三万人，执湝及广宁王孝珩。')]),
        ('r06-war-577-northern-revolt', -577, ['war'], '北周讨伐稽胡诸部，击破其军并擒获首领没铎', [('v173-y-577-p47', '周人既克关东，将讨稽胡，议欲穷其巢穴。齐主宪曰：「步落稽种类既，又山谷险绝，王师一举，未可尽除。且当翦其魁首，余加慰抚。」周主从之，以宪为行军元帅，督诸军讨之。至马邑，分道俱进。没铎分遣其党天柱守河东，穆支守河西，据险以拒之。宪命谯王俭击天柱，滕王逌击穆支，并破之，斩首万余级。赵王招击没铎，禽之，余众皆降。')]),
        ('r06-war-577-shaoyi', -577, ['war'], '高绍义与突厥军南下争夺并州，战败退保北朔州', [('v173-y-577-p54', '高宝宁自黄龙上表劝进于高绍义，绍义遂称皇帝，改元武平，以宝宁为丞相。突厥佗钵可汗举兵助之。'), ('v173-y-577-p21', '绍义与灵州刺史袁洪猛引兵南出，欲取并州。至新兴，而肆州已为周守，前隧二仪同以所部降周。周兵击显州，执刺史陆琼，复攻拔诸城。绍义还保北朔州。周东平公神举将兵逼马邑，绍义战败，北奔突厥')]),
        ('r06-war-578-pengcheng', -578, ['war'], '周军切断清口水路，王轨击溃陈军并俘获吴明彻', [('v173-y-578-p2', '吴明彻围周彭城，环列舟舰于城下，攻之甚急。'), ('v173-y-578-p2', '王轨引兵轻行，据淮口，结长围，以铁锁买车轮数百，沈之清水，以遏陈船归路；军中忷惧。'), ('v173-y-578-p3', '甲子，明彻决堰，乘水势退，冀以入淮。至清口，水势渐微舟舰并碍车轮，不复得过。王轨引兵围而蹙之，众溃。明彻为周人所执，将士三万并器械辎重皆没于周。')]),
        ('r06-war-578-turkish-yingzhou', -578, ['war'], '突厥侵入北周幽州并杀掠官民', [('v173-y-578-p12', '夏，四月，庚申，突厥寇周幽州，杀掠吏民。')]),
        ('r06-war-578-fanyang', -578, ['war'], '北周神举攻陷范阳，擒获卢昌期', [('v173-y-578-p25', '幽州人卢昌期，起兵据范阳，迎绍义绍义引突厥兵赴之。周遣柱国东平公神举将兵讨昌期。绍义闻幽州总管出兵在外，欲乘虚袭蓟，神举遣大将军宇文恩将四千人救之，半为绍义所杀。会神举克范阳，擒昌期')]),
        ('r06-war-578-turkish-jiuquan', -578, ['war'], '突厥侵扰北周边境并围攻酒泉，杀掠居民', [('v173-y-578-p36', '十一月，突厥寇周边，围酒泉，杀掠吏民。')]),
        ('r06-war-579-huainan', -579, ['war'], '周军攻取寿阳、黄城、广陵与霍州', [('v173-y-579-p33', '以郧公孝宽为行军元帅，帅行军总管杞公亮、郕公梁士彦寇淮南。'), ('v173-y-579-p39', '戊戌，周军进围寿阳。'), ('v173-y-579-p43', '戊申，韦孝宽拔寿阳，杞公亮拔黄城，梁士彦拔广陵；辛亥，又取霍州。')]),
        ('r06-war-579-chen-response', -579, ['war'], '陈军部署水陆诸军进入淮南方向应对北周进攻', [('v173-y-579-p43', '癸卯，任忠帅步骑七千趣秦郡；丙午，仁威将军鲁广达帅众入淮；是日，樊毅将水军二万自东关入焦湖，武毅将军萧摩诃帅步骑趣历阳。')]),
        ('r06-war-579-zhou-fashang', -579, ['war'], '周法尚诱伏击败陈军樊猛部，陈军死者近八千', [('v173-y-579-p50', '法尚阳为畏惧，自保江曲，战而伪走，伏兵邀之，猛仅以身免，没者几八千人。')]),
        ('r06-war-580-yang-liang', -580, ['war'], '杞公亮袭击韦孝宽未成，被追击斩杀', [('v174-y-580-p6', '亮夜将数百骑袭孝宽营，不克而走戊子，孝宽追斩之，温亦坐诛。')]),
        ('r06-war-580-yuchi-revolt', -580, ['war'], '尉迟迥在相州起兵反抗杨坚并控制多州', [('v174-y-580-p30', '集文武士民，登城北楼，令之曰：「杨坚藉后父之势，挟幼主以作威福，不臣之迹，暴于行路。吾与国舅甥，任兼将相；先帝处吾于此，本欲寄以安危。今欲与卿等纠合义勇，以匡国庇民，何如﹖」众咸从命。迥乃自称大总管，承制置官司。'), ('v174-y-580-p36', '周青州总管尉迟勤，迥之弟子也。初得迥书，表送之，寻亦从迥。迥所统相、卫、黎、洛、贝赵、冀、瀛、沧，勤所统青、齐、胶、光、莒等州皆从之，众数十万。')]),
        ('r06-war-580-qin-river', -580, ['war'], '高颎与韦孝宽击败尉迟惇军并渡过沁水', [('v174-y-580-p53', '高颎至军，为桥于沁水。尉迟惇于上流纵火袰，颎豫为土狗以御之。惇布陈二十余里，麾兵少却，欲待孝宽军半渡而击之；孝宽因其却，鸣鼓齐进。军既渡，颎命焚桥，以绝士卒反顾之心。惇兵大败，单骑走。孝宽乘胜进，追至邺。')]),
        ('r06-war-580-yecheng', -580, ['war'], '尉迟迥与援军在邺城南被击败，迥退守城中后自杀', [('v174-y-580-p54', '迥与惇及惇弟西都公佑，悉将其卒十三万陈于城南，迥别统万人，皆绿巾、锦袄，号「黄龙兵」。迥弟勤帅众五万，自青州赴迥，以三千骑先至。'), ('v174-y-580-p54', '迥军大败，走保邺城。考宽纵兵围之，李询及思安伯代人贺娄子干先登。'), ('v174-y-580-p55', '迥掷弓于地，骂左丞相极口而自杀。')]),
        ('r06-war-580-tanrang', -580, ['war'], '于仲文击破檀让军并攻取梁郡、曹州、成武、金乡等地', [('v174-y-580-p57', '檀让拥众数万，仲文以羸师挑战而伪北，让不设备；仲文还击，大破之，生获五千余人，斩首七百级。进攻梁郡，迥守将刘子宽弃城走。仲文进击曹州，获迥所署刺史李仲康。檀让之余众屯成武，仲文袭击，破之，遂拔成武。'), ('v174-y-580-p57', '仲文执之，遂取金乡。')]),
        ('r06-war-580-siman-xiaonan', -580, ['war'], '北周军击败司马消难部并收复其控制的城邑', [('v174-y-580-p65', '顺州刺史周法尚王能拒，弃城走，消难虏其母弟而南。樊毅救消难，不及，周亳州总管元景山击之，毅掠居民而去。'), ('v174-y-580-p65', '一日三战三捷。毅退保甑山镇，城邑为消难所据者，景山皆复取之。')]),
        ('r06-war-580-guo-mo', -580, ['war'], '陈军夺取周军郭默城与佑州城', [('v174-y-580-p61', '智武将军鲁广达克周之郭默城。'), ('v174-y-580-p61', '淳于陵克佑州城。')]),
        ('r06-war-580-guangling', -580, ['war'], '周军击退陈纪、萧摩诃对广陵的进攻', [('v174-y-580-p66', '陈纪、萧摩诃攻广陵，周吴州总管于顗击破之。')]),
        ('r06-war-580-wangqian', -580, ['war'], '梁睿击败王谦军并攻陷成都，王谦被擒斩', [('v174-y-580-p72', '睿奋击，屡破之，蜀人大骇。'), ('v174-y-580-p72', '睿自剑阁入，进逼成都。'), ('v174-y-580-p72', '睿击之，谦战败，将入城，惎、虔以城降。'), ('v174-y-580-p72', '戊寅，睿斩谦及高阿那肱，剑南平。')]),
        ('r06-war-580-yang-yongan', -580, ['war'], '达奚儒击败杨永安，平定沙州', [('v174-y-580-p73', '十一月，甲辰，周达奚儒破杨永安，沙州平。')]),
        ('r06-war-581-tuyuhun', -581, ['war'], '元谐两次击败吐谷浑军并俘斩万余人', [('v175-y-581-p29', '谐击破吐谷浑于丰利山，又败其太子可博汗于青海，俘斩万计。')]),
        ('r06-war-581-gu-shu', -581, ['war'], '周罗黄攻取故墅', [('v175-y-581-p30', '九月，庚午，将军周罗黄攻隋故墅，拔之。')]),
        ('r06-war-582-chen-nan', -582, ['war'], '陈军攻取涢口、甑山、沌阳等地，隋军退守', [('v175-y-582-p11', '隋元景山出汉口，遣上开府仪同三司邓孝儒将卒四千攻甑山。镇将军陆纶以舟师救之，为孝儒所败；涢口、甑山、沌阳守将皆弃城走。')]),
        ('r06-war-582-chickenhead', -582, ['war'], '韩僧寿与李充击败突厥军', [('v175-y-582-p15', '隋大将军韩僧寿破突厥于鸡头山，上柱国李充跛突厥于河北山。')]),
        ('r06-war-582-ma-yi', -582, ['war'], '李光在马邑击败突厥军，贺娄子干又于可洛峐击败突厥', [('v175-y-582-p21', '隋上柱国李光败突厥于马邑。突厥又寇兰州，凉州总管贺娄子干败之于可洛峐。')]),
        ('r06-war-582-zhou-pan', -582, ['war'], '达奚长儒率两千人鏖战三日，击退突厥十余万军', [('v175-y-582-p28', '行军总管达奚长儒将兵二千，与突厥沙钵略可汗遇于周盘，沙钵略有众十余万，军中大惧。长儒神色慷慨，且战且行，为虏所冲，散而复聚，四面抗拒。转鬬三日，昼夜凡十四战，五兵咸尽，士卒以拳殴之，手皆骨见，杀伤万计。虏气稍夺，于是解去。')]),
        ('r06-war-582-border-raids', -582, ['war'], '突厥攻破隋军数处驻地并大掠北方六郡', [('v175-y-582-p29', '冯昱屯夕弗泊，兰州总管叱列长叉守临洮，上柱国李崇屯幽州，皆为突厥所败。于是突厥纵兵自木硖、石门两道人寇武威、天水、金城、上郡、弘化、延安，六畜咸尽。')]),
        ('r06-war-583-baidau', -583, ['war'], '李充与长孙晟突袭白道，大破沙钵略可汗军', [('v175-y-583-p17', '己卯，与沙钵略可汗遇于白道。李充言于爽曰：「突厥狃于骤胜，必轻我而无备，以精兵袭之，何破也。」诸将多以为疑，唯长史李彻赞成之，遂与充帅精骑五千掩击突厥，大破之。沙钵略弃所服金甲，潜草中而遁。')]),
        ('r06-war-583-baoning', -583, ['war'], '阴寿攻克和龙，平定高宝宁势力', [('v175-y-583-p18', '幽州总管阴寿帅步骑十万出卢龙塞，击高寇，宁。寇宁求救于突厥，突厥方御隋师，不能救。庚辰，宝宁弃城奔碛北，和龙诸县悉平。')]),
        ('r06-war-583-mana', -583, ['war'], '李晃击破突厥于摩那度口', [('v175-y-583-p24', '五月，癸卯，隋行军总管李晃破突厥于摩那度口。')]),
        ('r06-war-583-gaoyue', -583, ['war'], '史万岁斩突厥勇士，窦荣定迫使突厥撤军请和', [('v175-y-583-p28', '壬戌，将战，荣定遣人谓突厥曰：「士卒何罪而杀之！但当各遣一壮士决胜负耳。」突厥许诺，因遣一骑挑战。荣定遣万岁出应之，万岁驰斩其首而还。突厥大惊，不敢复战，遂请盟，引军而去。')]),
        ('r06-war-583-tuyuhun', -583, ['war'], '梁远在尔汗山击败吐谷浑军', [('v175-y-583-p31', '六月，庚辰，隋行军总管梁远破吐谷浑于尔汗山。')]),
        ('r06-war-583-li-chong', -583, ['war'], '李崇坚守砂城抵御突厥围攻，最终战死', [('v175-y-583-p32', '突厥寇幽州，隋幽州总管广宗壮公李崇帅步骑三千拒之。转战十余日，师人多死，遂保砂城。突厥园之，城荒颓，不可守御，晓夕力战，又无所食，每夜出掠虏营，得六畜以继军粮，突厥畏之，厚为其备，每夜中结陈以待之。崇军苦饥，出辄遇敌，死亡略尽，及明，奔还城者尚百许人，然多重伤，不堪更战。突厥意欲降之，遣使谓崇曰：「若来降者，封为特勒。」崇知不免，令其士卒曰：「崇丧师徒，罪当万死。今日鹈命，以谢国家。汝俟吾死，且可降贼，便散走，努力还乡。若见至尊，道崇此意。」乃挺刃突陈，复杀二人，突厥乱射，杀之。')]),
        ('r06-famine-584-guanzhong', -584, ['famine'], '关中发生饥荒，隋主前往洛阳', [('v176-y-584-p17', '隋主以关中饥，行如洛阳。')]),
        ('r06-war-585-zhangdabao', -585, ['war'], '章大宝杀死接任刺史李晕并起兵反叛，后被擒', [('v176-y-585-p3', '丰州刺史章大宝，昭达之子也，在州贪纵，朝廷以太仆卿李晕代之。晕将至，辛酉，大宝袭杀晕，举兵反。'), ('v176-y-585-p6', '章大宝遣其将杨通攻建安，不克。台军将至，大宝众溃，逃入山，为追兵所擒，夷三族。')]),
        ('r06-war-585-nanchen', -585, ['war'], '陈军湛文彻进犯隋和州，被费首击败擒获', [('v176-y-585-p15', '九月，将军湛文彻侵隋和州，隋仪同三司费首击擒之。')]),
        ('r06-war-585-shabolue', -585, ['war'], '沙钵略可汗西征击败阿波可汗', [('v176-y-585-p12', '沙钵略因西击阿波，破之。')]),
        ('r06-war-585-abba', -585, ['war'], '隋军击退阿拔国对沙钵略妻子的袭掠', [('v176-y-585-p12', '而阿拔国乘虚掠其妻子；官军为击阿拔，败之，所获悉与沙钵略。')]),
        ('r06-war-587-jiangling-surrender', -587, ['war'], '后梁安平王岩等率十万人归降陈朝', [('v176-y-587-p15', '隋主以梁主在外，遣武乡公崔弘度将兵戍江陵。军至都州，梁主叔父太傅安平王岩、弟荆州刺史义兴王瓛等恐弘度袭之，乙丑，遣都官尚书沈君公诣荆州刺史宜黄侯慧纪请降。九月，庚寅，慧纪引兵至江陵城下。辛卯，岩等驱文、武、男、女十万口来奔。')]),
        ('r06-war-588-liutoutan', -588, ['war'], '杨素夜袭狼尾滩，击败并俘虏守将戚昕部', [('v176-y-588-p16', '杨素引舟师下三峡，军至流头滩。将军戚昕以青龙百余艘，守狼尾滩，地势险峭，隋人患之。素曰：「胜负大计，在此一举。若昼日下船，彼见我虚实，滩流迅邀，制不由人，则吾失其便；不如以夜掩之。」素亲帅黄龙数千艘，衔枚而下，遣开府仪同三司主长袭引步卒自南岸击昕别栅，大将军刘仁恩帅甲骑自北岸趣白沙，迟明而至，击之；昕败走，悉俘其众，劳而遣之，秋毫不犯。')]),
        ('r06-war-589-caishi', -589, ['war'], '韩擒虎夜渡长江并攻克采石', [('v177-y-589-p1', '韩擒虎将五百人自横江宵济采石，守者皆醉，遂克之。')]),
        ('r06-war-589-jingkou', -589, ['war'], '贺若弼攻取京口并俘获刺史黄恪', [('v177-y-589-p3', '庚午，贺若弼攻拔京口，执南徐州刺史黄恪。')]),
        ('r06-war-589-gushu', -589, ['war'], '韩擒虎攻取姑孰并俘获守将樊巡', [('v177-y-589-p4', '辛未，韩擒虎进攻姑孰，半日，拔之，执巡及其家口。')]),
        ('r06-war-589-qikou', -589, ['war'], '王世积在蕲口击败陈军纪瑱部', [('v177-y-589-p7', '蕲州总管王世积以舟师出九江，破陈将纪瑱于蕲口，陈人大骇，降者相继。')]),
        ('r06-war-589-jianshan', -589, ['war'], '贺若弼在蒋山击溃陈军，俘获萧摩诃', [('v177-y-589-p10', '陈兵得人头，皆走献陈主求赏，弼知其骄惰，更引兵趣孔范；范兵暂交即走，陈诸军顾之，骑卒乱溃，不可复止，死者五千人。员明擒萧摩诃，送于弼，弼牵斩之，摩诃颜色自若，弼乃释而礼之。')]),
        ('r06-war-589-jianye', -589, ['war'], '任忠率隋军进入建康，陈叔宝被俘，陈朝都城失守', [('v177-y-589-p11', '时韩擒虎自新林进军，忠已帅数骑迎降于石子冈。领军蔡征守朱雀航，闻擒虎将至，众惧而溃。忠引擒虎军直入朱雀门，陈人欲战，忠挥之曰：「老夫尚降，诸军何事！」众皆散走。'), ('v177-y-589-p13', '贺若弼乘胜至乐游苑，鲁广达犹督余兵苦战不息，所杀获数百人，会日暮，乃解甲，面台再拜恸哭，谓众曰：「我身不能救国，负罪深矣！」士卒皆流涕歔欷，遂就擒。诸门卫皆走，弼夜烧北掖门入，闻韩擒虎已得陈叔宝')]),
        ('r06-war-589-shangjiang', -589, ['war'], '杨素攻破陈军巫峡防线，陈上江诸州陆续投降', [('v177-y-589-p19', '杨素、刘仁恩奋兵击之，四十余战，忠肃守险力争，隋兵死者五千余人，陈人尽取其鼻以求功赏。既而隋师屡捷，获陈之士卒，三纵之。忠肃弃栅而遁，素徐去其锁；忠肃复据荆门之延洲，素遣巴蜑千人，乘五牙四艘，以拍竿碎其十余舰，遂大破之，俘甲士二千余人，忠肃仅以身免。'), ('v177-y-589-p19', '陈慧纪帅将士三万人，楼船千余艘，沿江而下，欲入援建康，为秦王俊所拒，不得前。')]),
        ('r06-war-589-wu-rebellion', -589, ['war'], '萧瓛组织吴地抵抗隋军，后被击败擒杀', [('v177-y-589-p22', '陈吴州刺史萧瓛能得物情，陈亡，吴人推瓛为主，右卫大将军武川宇文述帅行军总管元契、张默言等讨之。'), ('v177-y-589-p22', '述进破其栅，回兵击瓛，大破之；又遣兵别道袭吴州，王褒衣道士服弃城走。瓛以余众保包山，燕荣击破之。瓛将左右数人匿民家，为人所执。')]),
        ('r06-war-589-xiangzhou', -589, ['war'], '隋军击败岳阳王叔慎部并擒获叔慎', [('v177-y-589-p23', '叔慎遣其将陈正理与樊通拒战，兵败。冑乘胜入城，禽叔慎、仁恩，破邬居业于横桥，亦擒之，俱送秦王俊，斩于汉口。')]),
        ('r06-war-589-lingnan', -589, ['war'], '韦洸攻入岭南并平定当地抵抗', [('v177-y-589-p24', '陈豫章太守徐璒据南康拒之，洸等不得进。晋王广遣陈叔宝遗夫人书，谕以国亡，使之归隋。夫人集首领数千人，尽日恸哭，遣其孙冯魂帅众迎洸。洸击斩徐璒，入，至广州，说谕岭南诸州皆定')]),
        ('r06-war-590-jiangnan-rebellion', -590, ['war'], '杨素平定江南多地反叛，击败并擒获沈智慧等首领', [('v177-y-590-p9', '江表自东晋已来，刑法疏缓，世族陵驾寒门；平陈之后，牧民者尽更变之。饶州吴世华、温州沈孝彻、泉州王国庆、杭州杨宝英、交州李春等皆自称大都督，攻陷州县。陈之故境，大抵皆反，大者有众数万，小者数千，共相影响，执县令'), ('v177-y-590-p11', '素帅舟自杨子津入，击贼帅棨莫问于京口，破之。进击晋陵贼帅顾世兴。无锡贼帅叶略，皆平之。沈玄捏败走，素追擒之。高志慧据浙江东岸为营，周亘百余里，船舰被江；素击之。'), ('v177-y-590-p13', '素又破沈孝彻于温州，步道向天台，指临海，逐捕遗逸，前后百余战，高智慧走保闽、越。')]),
        ('r06-war-590-guangzhou', -590, ['war'], '洗夫人等击败番禺叛军并解除广州之围', [('v177-y-590-p17', '番禺夷王仲宣反，岭南首领多应之，引兵围广州。韦洸中流矢卒，沼以其副慕容三藏检校广州道行军事。又诏给事郎裴矩巡抚岭南，矩至南康，得兵数千人。仲宣遣别将周师举围东衡州，矩与大将军鹿愿击斩之，进至南海。'), ('v177-y-590-p18', '高凉洗夫人遣其孙冯暄将兵救广州，暄与贼将陈佛智素善，逗留不进；夫人知之，大怒，遣使执暄，击州狱，更遣孙盎出讨佛智，斩之。进会鹿愿于南海，与慕容三藏合击仲宣，仲宣众溃，广州获全。')]),
        ('r06-war-596-tangut', -596, ['war'], '隋军讨降党项部众', [('v178-y-596-p4', '党项宝会州，诏发陇西兵讨降之。')]),
        ('r06-war-597-nanning', -597, ['war'], '史万岁深入南中击破爨翫部三十余部', [('v178-y-597-p0', '乃以左领军将军史万岁为行军总管，帅众击之，入自蜻蛉川，至于南中。夷人前后屯据要害，万岁皆击破之；过诸葛亮纪功碑，渡西洱河，入渠滥川，行千余里，破其三十余部，虏获男女二万余口。诸夷大惧，遣使请降')]),
        ('r06-war-597-liguangshi', -597, ['war'], '周法尚击败并追杀桂州叛将李光仕', [('v178-y-597-p2', '桂州俚帅李光仕作乱，帝遣上柱国王世积与前桂州总管周法尚讨之，法尚发岭南兵，世积发岭北兵，俱会尹州。世积所部遇瘴，不能进，顿于衡州，法尚独讨之。光仕战败，帅劲兵走保白石洞。法尚大获家口，其党有来降者，辄以妻子还之，居旬日，降者数千人；光仕众溃而走，追斩之。')]),
        ('r06-war-597-lishixian', -597, ['war'], '虞庆则平定桂州人李世贤之乱', [('v178-y-597-p18', '秋七月，桂州人李世贤反，上议讨之。诸将数人请行，上不许，顾右武候大将军虞庆则曰：「位居宰相，爵乃上公，国家有贼，遂无行意，何也﹖」庆则拜谢，恐惧，乃以庆则为桂州道行军总管，讨平之。')]),
        ('r06-war-598-liaoxi', -598, ['war'], '高丽王元率靺鞨军侵犯辽西，被韦冲击退', [('v178-y-598-p1', '高丽王元帅靺鞨之众万余寇辽西，营州总管韦冲击走之。')]),
        ('r06-war-599-tujue-longwall', -599, ['war'], '都蓝联合达头突袭突利并击败其部众', [('v178-y-599-p3', '都蓝闻之，与达头可汗结盟，合兵掩袭突利，大战长城下，突利大败。都蓝尽杀其兄弟子侄，遂渡河入蔚州。')]),
        ('r06-war-599-tribal-battles', -599, ['war'], '赵仲卿与杨素分别击败突厥军，达头可汗重伤败走', [('v178-y-599-p5', '高颎使上柱国赵仲卿将兵三千为前锋，至族蠡山，与突厥遇，交战七日，大破之；追奔至乞伏泊，复破之，虏千余口，杂畜万计。突厥复大举而至，仲卿为方陈，四面拒战，凡五日。会高颎大兵至，合击之，突厥败走，追度白道，踰秦山七百余里而还。杨素军与达头遇。'), ('v178-y-599-p5', '周罗黄曰：「贼陈未整，请击之。」帅精骑逆战，素以大兵继之，突厥大败，达头被重创而遁，杀伤不可胜计，其众号哭而去。')]),
        ('r06-war-599-hangan', -599, ['war'], '突厥攻打代州，韩洪战败后赵仲卿截击并斩首千余', [('v178-y-599-p20', '达头骑十万来寇，韩洪军大败，仲卿自乐宁镇邀击，斩首千余级。')]),
        ('r06-war-600-lixinglin', -600, ['war'], '张衡率军平定熙州李英林叛乱', [('v179-y-600-p0', '春，二月，熙州人李英林反。三月，辛卯，以扬州总管司马河内张衡为行军总管，帅步骑五万讨平之。')]),
        ('r06-war-600-turkish-chase', -600, ['war'], '长孙晟以毒水迫退突厥并追斩千余人', [('v179-y-600-p3', '晟以突厥饮泉，易可行毒，因取诸药毒水上流，突厥人畜饮之多死，于是大惊曰：「天雨恶水，其亡我乎！」因夜遁。晟追之，斩首千余级。')]),
        ('r06-war-600-dajingshan', -600, ['war'], '史万岁在大斤山击败达头可汗并追入沙漠', [('v179-y-600-p4', '史万岁出塞，至大斤山，与虏相遇。达头遣使问：「隋将为谁﹖」候骑报：「史万岁也。」突厥复问：「得非敦煌戍卒乎﹖」候骑曰：「是也。」达头惧而引去。万岁驹追百余里，纵击，大破之，斩数千级；逐北，入碛数百里，虏达遁而还。')]),
        ('r06-war-601-steppe', -601, ['war'], '突厥步迦可汗攻败代州韩弘部', [('v179-y-601-p4', '突厥步迦可汗犯塞，败代州总管韩弘于恒安。')]),
        ('r06-war-601-liao-rebellion', -601, ['war'], '卫文升安抚山獠并解除大牢镇之围', [('v179-y-601-p10', '山獠作乱，以卫尉少卿洛阳卫文升为资州刺史镇抚之。文升名玄，以字行。初到官，獠方攻大牢镇，文升单骑造其营，谓曰：「我是刺史，衔天子诏，赡养汝等，勿惊惧也！」群獠莫敢动。于是说以利害，渠帅感悦，解兵而去，前后归附者十余万口。')]),
        ('r06-war-601-five-prefectures', -601, ['war'], '冯盎平定潮、成等五州獠人叛乱', [('v179-y-601-p11', '潮、成等五州獠反，高州酋长冯盎驰诣京帅，请讨之。帝敕杨素与盎论贼形势，素叹曰：「不意蛮夷中有如是人！」即遣盎发江、岭兵击之。事平，除盎汉阳太守。')]),
        ('r06-war-602-qimin-raids', -602, ['war'], '杨素追击掠夺启民部众的突厥军并夺回人畜', [('v179-y-602-p1', '突厥思力俟斤等南渡河，掠启民男女六千口、杂畜二十余万而去。杨素帅诸军追击，转战六十余里，大破之，突厥北走。素复进追，夜，乃之，恐其越逸，令其骑稍后，亲引两骑并降突厥二人与虏并行，虏不之觉；候其顿舍未定，趣后骑掩击，大破之，悉得人畜以归启民。')]),
        ('r06-war-602-lifozhi', -602, ['war'], '刘方击败交州李佛子军并迫使其投降', [('v179-y-602-p23', '交州俚帅李佛子作乱，据越王故城，遣其兄子大权据龙编城，其别帅李普鼎据乌延城。杨素荐瓜州刺史长安刘方有将帅之略，诏以方为交州道行军总管，统二十七营而进。'), ('v179-y-602-p23', '至都隆岭，遇贼，击破之。进军临佛子营，先谕以祸福。佛子惧，请降，送之长安。')]),
        ('r06-war-604-hanliang-revolt', -604, ['war'], '汉王杨谅起兵反隋，控制多州并分道进攻京师', [('v180-y-604-p9', '谅遂发兵反。'), ('v180-y-604-p11', '于是从谅反者十九州岛。'), ('v180-y-604-p14', '诈称谅宫人还长安，门司弗觉，径入蒲州，城中豪杰亦有应之者')]),
        ('r06-war-604-yanmen', -604, ['war'], '李景坚守代州，击退汉王杨谅部乔钟葵军', [('v180-y-604-p14', '代州总管天水李景发兵拒谅，谅遣其将刘暠袭景；景击斩之。谅复遣乔锺葵帅劲勇三万攻之，景战士不过数千，加以城池不固，为锺葵所攻，崩毁相继，景且战且筑，士卒皆殊死鬬；锺葵屡败。')]),
        ('r06-war-604-puzhou', -604, ['war'], '杨素夜袭蒲州，击败守军并迫使王聃投降', [('v180-y-604-p15', '杨素将轻骑五千袭王聃、纥单贵于蒲州，夜，至河际，收商贾船，得数百艘，船内多置草，践之无声，遂衔枚而济；迟明，击之；纥单贵败走，聃惧，以城降。')]),
        ('r06-war-604-heyang', -604, ['war'], '史祥击败余公理军，随后迫使綦良部溃散', [('v180-y-604-p18', '公理屯河阳，祥具舟南岸，公理聚兵当之。祥简精锐于下流潜济，公理闻之，引兵拒之，战于须水。公理未成列，祥击之，公理大败。祥东趣黎阳，綦良军不战而溃。')]),
        ('r06-war-604-gaobi', -604, ['war'], '杨素击破汉王杨谅主力并迫使其投降', [('v180-y-604-p20', '北军不知所为，自相蹂践，杀伤数万。'), ('v180-y-604-p22', '杨素进击谅，大破之，擒萧摩诃。谅退保晋阳，素进兵围之，谅穷蹙，请降，余党悉平。')]),
        ('r06-war-605-linyi', -605, ['war'], '刘方击败林邑军并攻入其国都，取得重大伤亡', [('v180-y-605-p4', '刘方新平交州，乃授方驩州道行军总管，经略林邑。方遣钦州刺史宁长真等以步骑万余出越裳，方亲帅大将军张愻等以舟师出比景，是月，军至海口。'), ('v180-y-605-p10', '师渡阇黎江，林邑兵乘巨象四面而至。方战不利，乃多掘小坑，草覆其上，以兵挑之，既战，伪北；林邑逐之，象多陷地颠踬，转相惊骇，军遂乱。方以弩射象，象却了，蹂其陈，因以锐师继之，林邑大败，俘馘万计。方引兵追之，屡战皆捷，过马援铜柱南，八日至其国都。夏，四月，梵志弃城走入海。方入城，获其庙主十八')]),
        ('r06-war-605-khitan', -605, ['war'], '韦云起率突厥军突袭契丹营地并掳获四万人', [('v180-y-605-p15', '契丹寇营州，诏通事谒者韦云起护突厥兵讨之，启民可汗发骑二万，受其处分。'), ('v180-y-605-p15', '云起既入其境，使突厥诈云杨柳城与高丽交易，敢漏泄事实者斩。契丹不为备，去其营五十里，驰进袭之，尽获其男女四万口，杀其男子，以女子及畜产之半赐突厥，余皆收之以归。')]),
        ('r06-war-607-tiele', -607, ['war'], '冯孝慈出敦煌击退犯边的铁勒军', [('v180-y-607-p21', '铁勒寇边，帝遣将军冯孝慈出敦煌击之，不利。铁勒寻遣使谢罪，请降；帝使裴矩慰抚之。')]),
        ('r06-famine-548-jiankang', -548, ['famine'], '侯景之乱中建康发生饥荒，人相食', [('v161-y-548-p51', '又食石头常平诸仓既尽，军中乏食；乃纵士卒掠夺民米及金帛子女。是后米一升至十八万钱，人相食，饿死者什五六。')]),
        ('r06-disaster-550-drought-locust', -550, ['disaster', 'famine'], '江南旱蝗造成饥荒与大量死亡', [('v163-y-550-p22', '时江南连年旱蝗，江、扬尤甚，百姓流亡，相与入山谷、江湖，采草根、木叶，菱芡而食之，所在皆尽，死者蔽野。')]),
        ('r06-famine-552-jiangdong', -552, ['famine'], '江东饥乱，大量遗民饿死', [('v164-y-552-p38', '时江东饥乱，饿死者什八九，遗民携老幼归之。')]),
        ('r06-disaster-556-flood', -556, ['disaster'], '连日暴雨导致平地积水丈余', [('v166-y-556-p18', '会连日大雨，平地水丈余，齐军昼夜坐立泥中')]),
        ('r06-disaster-557-locust', -557, ['disaster'], '河南、河北发生蝗灾', [('v167-y-557-p28', '河南、北大蝗。')]),
        ('r06-disaster-war-564-flood-battle', -564, ['disaster', 'war'], '大雨江涨，章昭达借洪水冲毁陈宝应水栅并击败其军', [('v169-y-564-p36', '会大雨江涨，昭达放筏冲宝应水栅，尽坏之，又出兵攻其步军。方合战')]),
        ('r06-disaster-famine-594-guanzhong', -594, ['disaster', 'famine'], '关中大旱，百姓饥荒并迁往洛阳就食', [('v178-y-594-p4', '关中大旱，民饥')]),
        ('r06-disaster-595-drought', -595, ['disaster'], '隋文帝因旱灾祈告上天', [('v178-y-595-p0', '柴燎祀天，以岁旱谢谢愆咎')]),
        ('r06-disaster-war-598-expedition', -598, ['disaster', 'war'], '隋军伐高丽遇水潦、风灾与疫病，撤军时伤亡惨重', [('v178-y-598-p3', '汉王谅军出临渝关，值水潦，馈运不继，军中乏食，复遇疾疫。周罗黄自东莱泛海趣平壤城，亦遭风，船多飘没。秋，九月，己丑，师还，死者什八九。')]),
        ('r06-disaster-600-earthquake', -600, ['disaster'], '天下发生地震', [('v179-y-600-p32', '天下地震')]),
    ]
    candidate_by_id = {c['id']: c for c in candidates}
    curated_source_ids = {sid for _, _, _, _, srcs in specs for sid, _ in srcs}
    # Previously provisional candidates retain their broad-recall role. Prior
    # paragraph-level reviewed rows are downgraded unless replaced by reviewed events.
    for event in events:
        event['status'] = 'provisional'
        event['reason'] = '保留为候选段记录；尚未完成具体事件拆分/合并和事件边界核验'
    events = [e for e in events if e['id'] not in curated_source_ids]
    curated = []
    for event_id, year, categories, title, srcs in specs:
        sources = []
        for cid, quote in srcs:
            if cid in candidate_by_id:
                c = candidate_by_id[cid]
                volume, source_year, anchor = c['volume'], c['year'], c['anchor']
                plain = c['text']
            else:
                match = re.fullmatch(r'v(\d+)-y(-?\d+)-p(\d+)', cid)
                volume, source_year, anchor = map(int, match.groups())
                if volume not in data_cache:
                    data_cache[volume] = json.loads((ROOT / f'dist/volume{volume}.json').read_text())
                yobj = next(y for y in data_cache[volume]['years'] if y['year'] == source_year)
                plain = yobj['paragraphs'][anchor]['plain']
            if quote not in plain:
                raise ValueError(f'quote is not substring of canonical plain: {cid}: {quote!r}')
            sources.append({'volume': volume, 'year': source_year, 'anchor': anchor, 'quote': quote})
        curated.append({'id': event_id, 'year': year, 'categories': categories, 'title': title,
                        'sources': sources, 'status': 'reviewed',
                        'reason': '逐条核对来源原文和同年相关段落，确认本年发生动作并按事件边界归并/拆分'})
    reviewed = {sid for _, _, _, _, srcs in specs for sid, _ in srcs}
    events.extend(curated)

    result = {
        'range': [151, 180], 'events': events, 'excluded': excluded,
        'coverage': {
            'candidateParagraphs': len(candidates),
            'modelReviewedParagraphs': len(reviewed_ids),
            'reviewedCandidateIds': sorted(reviewed_ids),
            'method': '1533个候选段均已逐条阅读并作事件或排除判定；事件级 reviewed 记录由人工核读的具体行动按本年事件边界拆分或合并来源，尚未完成事件归并核验的保留 provisional。所有引文逐条与 dist/volumeN.json 的 paragraphs[anchor].plain 子串核对。',
            'limitations': [
                '本批审查覆盖候选集1533段，不代表范围内每个原文段落都被全书扫描；候选生成的召回偏差可能导致漏项。',
                '仍有 provisional 事件尚未完成具体行动的拆并或跨卷来源归并，不应视为最终事件清单。',
                '战争叙述跨年、追叙旧事时，仍须按原文实际动作核定年份；无法从来源确认归年的事件不应强行归年。',
                '军队断粮不计为社会性饥荒；复合灾战段需区分受灾群体、战事和事件发生时间。',
            ],
        },
    }
    OUTPUT.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n')
    print(json.dumps({'candidates': len(candidates), 'events': len(events), 'excluded': len(excluded),
                      'statuses': Counter(e['status'] for e in events),
                      'categories': Counter(k for e in events for k in e['categories']),
                      'modelReviewedParagraphs': len(reviewed_ids)}, ensure_ascii=False))

if __name__ == '__main__':
    main()
